write_file({"content":"/* WebCraft 样式 —— 仿 Minecraft UI */
* { margin:0; padding:0; box-sizing:border-box; user-select:none; }
html,body { width:100%; height:100%; overflow:hidden; background:#000;
  font-family:"Courier New", Consolas, monospace; }
canvas#game { position:fixed; inset:0; width:100%; height:100%; display:block; }
.hidden { display:none !important; }
img { image-rendering: pixelated; }

/* ---------- HUD ---------- */
#hud { position:fixed; inset:0; pointer-events:none; }
#crosshair { position:absolute; left:50%; top:50%; width:22px; height:22px;
  transform:translate(-50%,-50%); mix-blend-mode:difference; }
.ch-v { position:absolute; left:50%; top:0; width:2px; height:100%; background:#ddd; transform:translateX(-50%); }
.ch-h { position:absolute; top:50%; left:0; height:2px; width:100%; background:#ddd; transform:translateY(-50%); }

#vignette { position:absolute; inset:0; pointer-events:none; opacity:0;
  background:radial-gradient(ellipse at center, rgba(255,0,0,0) 40%, rgba(190,0,0,.55) 100%);
  transition:opacity .12s; }
#waterOverlay { position:absolute; inset:0; background:rgba(18,52,148,.30); opacity:0; transition:opacity .2s; }

#hotbar { position:absolute; left:50%; bottom:8px; transform:translateX(-50%);
  display:flex; background:rgba(0,0,0,.45); padding:3px; border:2px solid rgba(0,0,0,.7); }
.slot { width:52px; height:52px; border:2px solid #5a5a5a; background:rgba(30,30,30,.55);
  display:flex; align-items:center; justify-content:center; position:relative; }
.slot img { width:44px; height:44px; }
.slot.sel { border:3px solid #fff; box-shadow:0 0 0 2px #000 inset; }
.slot .num { position:absolute; left:2px; top:0; font-size:10px; color:#ccc; text-shadow:1px 1px #000; }

#statusRow { position:absolute; left:50%; bottom:70px; width:496px; transform:translateX(-50%);
  display:flex; justify-content:space-between; }
#hearts, #hunger, #bubbles { display:flex; gap:1px; }
#hearts img, #hunger img, #bubbles img { width:18px; height:18px; }
#bubbles { position:absolute; right:0; bottom:104px; }
#statusRow { bottom:70px; }

#toast { position:absolute; left:50%; bottom:110px; transform:translateX(-50%);
  color:#fff; font-size:16px; font-weight:bold; text-shadow:2px 2px #000;
  opacity:0; transition:opacity .4s; }

#debug { position:absolute; left:6px; top:6px; color:#fff; font-size:13px; line-height:1.35;
  text-shadow:1px 1px #000; background:rgba(0,0,0,.25); padding:4px 8px; white-space:pre; }

/* ---------- 覆盖层（菜单） ---------- */
.overlay { position:fixed; inset:0; display:flex; align-items:center; justify-content:center;
  z-index:20; }
.menu-inner { text-align:center; color:#fff; }
#logo { font-size:72px; font-weight:900; letter-spacing:6px; color:#e8e8e8;
  text-shadow:4px 4px 0 #3a3a3a, 8px 8px 0 rgba(0,0,0,.5); margin-bottom:6px; }
#splash { color:#ffff00; font-size:18px; font-weight:bold; transform:rotate(-12deg);
  text-shadow:2px 2px #3f3f00; animation:splashPulse 1s infinite; margin-bottom:26px; }
@keyframes splashPulse { 0%,100%{transform:rotate(-12deg) scale(1);} 50%{transform:rotate(-12deg) scale(1.08);} }
.btn-col { display:flex; flex-direction:column; gap:10px; align-items:center; }
.btn { width:320px; padding:12px 0; font-family:inherit; font-size:17px; font-weight:bold; color:#e0e0e0;
  background:#6f6f6f; border:2px solid #000; cursor:pointer;
  box-shadow:inset 2px 2px 0 rgba(255,255,255,.4), inset -2px -2px 0 rgba(0,0,0,.45);
  text-shadow:2px 2px #383838; }
.btn:hover { background:#7d8fbe; color:#fff; }
#seedLine { margin-top:22px; font-size:13px; color:#bbb; text-shadow:1px 1px #000; }
#version { position:fixed; left:8px; bottom:6px; font-size:12px; color:#888; text-shadow:1px 1px #000; }
.pause-title { font-size:34px; font-weight:bold; text-shadow:3px 3px #000; margin-bottom:24px; }
.death-title { font-size:52px; font-weight:bold; color:#fff; text-shadow:4px 4px #300; margin-bottom:12px; }
.death-sub { font-size:16px; color:#eee; text-shadow:2px 2px #000; margin-bottom:20px; }
#death { background:rgba(120,0,0,.5); }
#helpBox, #helpBox2 { margin:14px auto 0; width:460px; text-align:left; font-size:13px; line-height:1.6;
  background:rgba(0,0,0,.55); border:2px solid #555; padding:10px 14px; color:#ddd; }

/* ---------- 物品栏 ---------- */
#inventory { position:fixed; inset:0; display:flex; align-items:center; justify-content:center;
  background:rgba(0,0,0,.55); z-index:15; }
.inv-panel { background:#c6c6c6; border:3px solid; border-color:#fff #555 #555 #fff; padding:12px 14px; }
.inv-title { color:#3f3f3f; font-weight:bold; font-size:16px; margin-bottom:10px; }
.inv-hint { font-size:11px; font-weight:normal; color:#666; margin-left:8px; }
#invGrid { display:grid; grid-template-columns:repeat(9, 46px); gap:2px; }
.inv-slot { width:46px; height:46px; background:#8b8b8b; border:2px solid; border-color:#373737 #fff #fff #373737;
  display:flex; align-items:center; justify-content:center; cursor:pointer; }
.inv-slot:hover { background:#a8a8d0; }
.inv-slot img { width:38px; height:38px; }
","path":"css/style.css"})

write_file({"content":"// Perlin 噪声（2D/3D）+ 哈希工具
window.WC = window.WC || {};
WC.noise = (function () {
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  function makePerlin(seed) {
    var p = new Uint8Array(512);
    var r = mulberry32(seed);
    var perm = [];
    for (var i = 0; i < 256; i++) perm[i] = i;
    for (var i = 255; i > 0; i--) {
      var j = (r() * (i + 1)) | 0;
      var tmp = perm[i]; perm[i] = perm[j]; perm[j] = tmp;
    }
    for (var i = 0; i < 512; i++) p[i] = perm[i & 255];

    function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
    function lerp(a, b, t) { return a + (b - a) * t; }
    function grad2(h, x, y) {
      switch (h & 7) {
        case 0: return x + y; case 1: return -x + y;
        case 2: return x - y; case 3: return -x - y;
        case 4: return x; case 5: return -x;
        case 6: return y; default: return -y;
      }
    }
    function grad3(h, x, y, z) {
      var g = h & 15;
      var u = g < 8 ? x : y;
      var v = g < 4 ? y : (g === 12 || g === 14 ? x : z);
      return ((g & 1) ? -u : u) + ((g & 2) ? -v : v);
    }
    // 2D Perlin，范围约 [-1,1]
    function n2(x, y) {
      var X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
      x -= Math.floor(x); y -= Math.floor(y);
      var u = fade(x), v = fade(y);
      var A = p[X] + Y, B = p[X + 1] + Y;
      return lerp(
        lerp(grad2(p[A], x, y), grad2(p[B], x - 1, y), u),
        lerp(grad2(p[A + 1], x, y - 1), grad2(p[B + 1], x - 1, y - 1), u), v) * 0.7;
    }
    // 3D Perlin
    function n3(x, y, z) {
      var X = Math.floor(x) & 255, Y = Math.floor(y) & 255, Z = Math.floor(z) & 255;
      x -= Math.floor(x); y -= Math.floor(y); z -= Math.floor(z);
      var u = fade(x), v = fade(y), w = fade(z);
      var A = p[X] + Y, AA = p[A] + Z, AB = p[A + 1] + Z;
      var B = p[X + 1] + Y, BA = p[B] + Z, BB = p[B + 1] + Z;
      return lerp(
        lerp(lerp(grad3(p[AA], x, y, z), grad3(p[BA], x - 1, y, z), u),
             lerp(grad3(p[AB], x, y - 1, z), grad3(p[BB], x - 1, y - 1, z), u), v),
        lerp(lerp(grad3(p[AA + 1], x, y, z - 1), grad3(p[BA + 1], x - 1, y, z - 1), u),
             lerp(grad3(p[AB + 1], x, y - 1, z - 1), grad3(p[BB + 1], x - 1, y - 1, z - 1), u), v), w);
    }
    return { n2: n2, n3: n3 };
  }

  // 分形叠加
  function fbm2(n, x, y, oct, lac, gain) {
    lac = lac || 2; gain = gain || 0.5;
    var amp = 1, freq = 1, sum = 0, norm = 0;
    for (var i = 0; i < oct; i++) {
      sum += amp * n.n2(x * freq, y * freq);
      norm += amp; amp *= gain; freq *= lac;
    }
    return sum / norm;
  }
  function fbm3(n, x, y, z, oct, lac, gain) {
    lac = lac || 2; gain = gain || 0.5;
    var amp = 1, freq = 1, sum = 0, norm = 0;
    for (var i = 0; i < oct; i++) {
      sum += amp * n.n3(x * freq, y * freq, z * freq);
      norm += amp; amp *= gain; freq *= lac;
    }
    return sum / norm;
  }

  // 坐标整数哈希 → [0,1)，确定性随机
  function hash2(x, z) {
    var h = Math.imul(x, 374761393) + Math.imul(z, 668265263);
    h = (h ^ (h >>> 13)) | 0;
    h = Math.imul(h, 1274126177);
    h = (h ^ (h >>> 16)) >>> 0;
    return h / 4294967296;
  }
  function hash3(x, y, z) {
    var h = Math.imul(x, 374761393) + Math.imul(y, 2246822519) + Math.imul(z, 668265263);
    h = (h ^ (h >>> 13)) | 0;
    h = Math.imul(h, 1274126177);
    h = (h ^ (h >>> 16)) >>> 0;
    return h / 4294967296;
  }

  return { mulberry32: mulberry32, makePerlin: makePerlin, fbm2: fbm2, fbm3: fbm3, hash2: hash2, hash3: hash3 };
})();
