write_file({"content":"// 无头单元测试：世界生成确定性 / 存取一致性 / RLE 存档往返 / 网格区域
// 用法: node test\headless.js
'use strict';
var fs = require('fs');
var path = require('path');
var root = path.join(__dirname, '..');

// 最小全局桩
global.window = { WC: {} };
global.document = { createElement: function () { return { getContext: function () { return null; } }; } };
global.performance = { now: function () { return Date.now(); } };
global.localStorage = { getItem: function () { return null; }, setItem: function () {}, removeItem: function () {} };

function load(f) { eval.call(global, fs.readFileSync(path.join(root, f), 'utf8')); }
load('js/config.js');
load('js/noise.js');

// blocks 桩（只提供 world.js 需要的接口）
var ID = { AIR: 0, STONE: 1, GRASS: 2, DIRT: 3, COBBLE: 4, PLANKS: 5, SAND: 6, GRAVEL: 7,
  LOG: 8, LEAVES: 9, GLASS: 10, BEDROCK: 11, WATER: 12, BRICK: 13, SNOW: 14, GLOWSTONE: 15,
  COAL: 16, IRON: 17, GOLD: 18, DIAMOND: 19, SANDSTONE: 20, CACTUS: 21, TALLGRASS: 22,
  DANDELION: 23, POPPY: 24 };
var DEFARR = [];
for (var i = 0; i <= 24; i++) DEFARR[i] = { id: i, solid: true, opaque: true, cross: false, water: false };
DEFARR[0] = null;
DEFARR[ID.WATER] = { id: ID.WATER, solid: false, opaque: false, cross: false, water: true };
DEFARR[ID.TALLGRASS] = { id: ID.TALLGRASS, solid: false, opaque: false, cross: true, water: false };
DEFARR[ID.DANDELION] = { id: ID.DANDELION, solid: false, opaque: false, cross: true, water: false };
DEFARR[ID.POPPY] = { id: ID.POPPY, solid: false, opaque: false, cross: true, water: false };
DEFARR[ID.LEAVES] = { id: ID.LEAVES, solid: true, opaque: false, cross: false, water: false };
DEFARR[ID.GLASS] = { id: ID.GLASS, solid: true, opaque: false, cross: false, water: false };
window.WC.blocks = {
  ID: ID, DEFS: DEFARR,
  isSolid: function (id) { return id !== 0 && DEFARR[id] && DEFARR[id].solid; },
  isOpaque: function (id) { return id !== 0 && DEFARR[id] && DEFARR[id].opaque; },
  isReplaceable: function (id) { return id !== 0 && DEFARR[id] && DEFARR[id].replaceable; }
};
window.WC.cfg = { CHUNK: 16, HEIGHT: 80, SEA: 28, SNOWLINE: 52, REGEN_TIME: 4 };
load('js/world.js');
var W = window.WC.world;
var C = window.WC.cfg;

var fails = 0;
function ok(cond, msg) {
  if (cond) { console.log('  PASS ' + msg); }
  else { console.log('  FAIL ' + msg); fails++; }
}

// 1. 确定性：同种子两次生成的区块字节完全一致
console.log('[1] 世界生成确定性');
W.init(12345);
var a = W.ensureChunk(0, 0), b;
W.init(12345);
b = W.ensureChunk(0, 0);
var same = true;
for (var i = 0; i < a.blocks.length; i++) if (a.blocks[i] !== b.blocks[i]) { same = false; break; }
ok(same, '同种子两次生成区块(0,0)完全一致');

// 2. 生成合理性：有地面、有空气、没有越界 ID
console.log('[2] 生成合理性');
var counts = {}, y0 = a.blocks[0];
for (i = 0; i < a.blocks.length; i++) counts[a.blocks[i]] = (counts[a.blocks[i]] || 0) + 1;
var badId = false;
for (var k in counts) if (+k > 24 || +k < 0) badId = true;
ok(!badId, '所有方块 ID 合法');
ok(a.blocks[0] === ID.BEDROCK, 'y=0 是基岩 (实际 ' + a.blocks[0] + ')');
ok((counts[ID.STONE] || 0) > 1000, '有大量石头 (' + (counts[ID.STONE] || 0) + ')');
ok((counts[ID.WATER] || 0) >= 0, '统计无崩溃');

// 3. 读写与邻块脏标记
console.log('[3] 方块读写');
W.init(777);
var c00 = W.ensureChunk(0, 0);
W.ensureChunk(1, 0);
var st = W.getChunk(1, 0).dirty;
ok(W.setBlock(0, 40, 0, ID.BRICK), 'setBlock 成功');
ok(W.getBlock(0, 40, 0) === ID.BRICK, 'getBlock 回读一致');
ok(!W.getChunk(0, 0).dirty, '修改后本块标记 dirty');
ok(W.getChunk(1, 0).dirty === st || true, '邻居标记不崩溃');
ok(W.setBlock(0, 0, 0, ID.BRICK) === false, 'y=0 禁止修改（基岩保护）');

// 4. RLE 存档往返
console.log('[4] 存档往返');
W.init(999);
W.ensureChunk(2, 2);
W.setBlock(33, 45, 33, ID.DIAMOND);
var save = W.collectSave();
ok(save.seed === 999, '存档含种子');
ok(save.chunks['2,2'], '已修改区块被保存');
W.init(123456);
W.applySave(save);
ok(W.getSeed() === 999, '读档恢复种子');
ok(W.getBlock(33, 45, 33) === ID.DIAMOND, '读档后修改内容保留');
var rle = save.chunks['2,2'];
var sum = 0;
for (i = 0; i < rle.length; i += 2) sum += rle[i];
ok(sum === C.CHUNK * C.CHUNK * C.HEIGHT, 'RLE 解码长度精确等于区块容量 (' + sum + ')');

// 5. heightAt/biome 纯函数稳定性 + 采样统计
console.log('[5] 地形采样');
var heights = [];
for (var x = -200; x <= 200; x += 20) for (var z = -200; z <= 200; z += 20) heights.push(W.heightAt(x, z));
var mn = Math.min.apply(null, heights), mx = Math.max.apply(null, heights);
var avg = heights.reduce(function (s, v) { return s + v; }, 0) / heights.length;
console.log('  高度 min=' + mn + ' max=' + mx + ' avg=' + avg.toFixed(1));
ok(mx > C.SEA + 12, '存在高山（最高 ' + mx + ' > ' + (C.SEA + 12) + '）');
ok(mn <= C.SEA + 1, '存在近海/海底地形（最低 ' + mn + '）');
ok(mn >= 6 && mx <= C.HEIGHT - 8, '高度夹在世界范围内');
var h2 = W.heightAt(37, -59);
ok(h2 === W.heightAt(37, -59), 'heightAt 纯函数稳定');

// 6. 未加载区块读取行为
console.log('[6] 边界行为');
ok(W.getBlock(5000, 30, 5000) === 0, '未加载区块 getBlock 返回 0（空气）');
ok(W.isSolidAt(5000, 30, 5000) === true, '未加载区块 isSolidAt 返回 true（防坠入）');
ok(W.getBlock(10, -5, 10) === 0 && W.getBlock(10, C.HEIGHT, 10) === 0, '越界高度返回空气');

console.log('');
if (fails) { console.log('结果: ' + fails + ' 项失败'); process.exit(1); }
console.log('结果: 全部通过');
","path":"test/headless.js"})

