{"content":"// 世界：区块存储 + 地形生成 + 方块读写 + 存档 RLE
window.WC = window.WC || {};
WC.world = (function () {
  var N = WC.noise, B = WC.blocks, C = WC.cfg;
  var ID = B.ID;
  var CH = C.CHUNK, H = C.HEIGHT, SEA = C.SEA;
  var chunks = new Map();
  var seed = 0, p1, p2;

  function init(s) {
    seed = s >>> 0;
    p1 = N.makePerlin(seed);
    p2 = N.makePerlin((seed ^ 0x9E3779B9) >>> 0);
    chunks.clear();
  }
  function getSeed() { return seed; }

  function key(cx, cz) { return cx + ',' + cz; }
  function lidx(x, y, z) { return (x * CH + z) * H + y; }

  // ---------- 纯函数式地形（与区块无关，可对任意世界坐标求值） ----------
  function heightAt(wx, wz) {
    var cont = N.fbm2(p1, wx * 0.0035, wz * 0.0035, 4);          // 大陆起伏
    var h = SEA + 3 + cont * 13;
    var hill = N.fbm2(p1, wx * 0.016 + 31.7, wz * 0.016 + 31.7, 4) * 0.5 + 0.5;
    h += hill * hill * 16;                                        // 丘陵
    var mMask = Math.max(0, N.fbm2(p2, wx * 0.0055 - 53.1, wz * 0.0055 - 53.1, 3) - 0.05);
    var ridge = 1 - Math.abs(N.fbm2(p1, wx * 0.021 - 53.1, wz * 0.021 - 53.1, 4));
    h += mMask * ridge * ridge * 34;                              // 山脊
    return Math.max(6, Math.min(H - 8, Math.floor(h)));
  }
  function tempAt(wx, wz) { return N.fbm2(p2, wx * 0.0024 + 7.3, wz * 0.0024 + 7.3, 3); }
  function humidAt(wx, wz) { return N.fbm2(p2, wx * 0.0024 - 71.9, wz * 0.0024 - 71.9, 3); }
  function biomeOf(h, t, hu) {
    if (h >= C.SNOWLINE || t < -0.42) return 'snow';
    if (t > 0.32 && hu < 0.08) return 'desert';
    if (hu > 0.14) return 'forest';
    return 'plains';
  }

  // 树木/仙人掌确定性放置（跨区块无缝：生成时扫描含边界的邻域）
  function treeAt(wx, wz) {
    var r = N.hash2(wx, wz);
    if (r >= 0.03) return 0;
    var h = heightAt(wx, wz);
    if (h <= SEA) return 0;
    var biome = biomeOf(h, tempAt(wx, wz), humidAt(wx, wz));
    if (biome === 'forest' && r < 0.030) return 4 + ((r * 997) | 0) % 3;
    if (biome === 'plains' && r < 0.004) return 4 + ((r * 997) | 0) % 3;
    if (biome === 'snow' && r < 0.006) return 4 + ((r * 997) | 0) % 2;
    if (biome === 'desert' && r < 0.007) return 2 + ((r * 997) | 0) % 2;
    return 0;
  }

  function setLocal(bl, x, y, z, id) {
    if (x < 0 || x >= CH || z < 0 || z >= CH || y < 0 || y >= H) return;
    bl[lidx(x, y, z)] = id;
  }
  function setLocalIfAir(bl, x, y, z, id) {
    if (x < 0 || x >= CH || z < 0 || z >= CH || y < 0 || y >= H) return;
    var i = lidx(x, y, z);
    if (bl[i] === 0) bl[i] = id;
  }

  function generateChunk(cx, cz) {
    var blocks = new Uint8Array(CH * CH * H);
    for (var lx = 0; lx < CH; lx++) for (var lz = 0; lz < CH; lz++) {
      var wx = cx * CH + lx, wz = cz * CH + lz;
      var h = heightAt(wx, wz);
      var t = tempAt(wx, wz), hu = humidAt(wx, wz);
      var biome = biomeOf(h, t, hu);
      for (var y = 0; y <= h; y++) {
        var id;
        if (y === 0 || (y < 3 && N.hash3(wx, y, wz) < 0.55 - y * 0.18)) id = ID.BEDROCK;
        else if (y === h) {
          if (h < SEA + 2) id = ID.SAND;
          else if (biome === 'desert') id = ID.SAND;
          else if (biome === 'snow') id = ID.SNOW;
          else id = ID.GRASS;
        } else if (y > h - 4) {
          if (biome === 'desert') id = (y <= h - 3) ? ID.SANDSTONE : ID.SAND;
          else id = ID.DIRT;
        } else {
          id = ID.STONE;
          if (y < 48) {
            var on = p2.n3(wx * 0.11, y * 0.13, wz * 0.11);
            if (on > 0.60) id = ID.COAL;
            else if (on < -0.64 && y < 36) id = ID.IRON;
          }
          if (id === ID.STONE && y < 24) {
            var gn = p1.n3(wx * 0.09 + 55.1, y * 0.09 + 55.1, wz * 0.09 + 55.1);
            if (gn > 0.70) id = ID.GOLD;
            else if (gn < -0.72 && y < 15) id = ID.DIAMOND;
          }
        }
        // 洞穴：双噪声意面 + 下方大空腔（海域下方不挖）
        if (id !== ID.BEDROCK && h > SEA + 1 && y > 4) {
          var a = p1.n3(wx * 0.055, y * 0.085, wz * 0.055);
          if (a > -0.10 && a < 0.10) {
            var b2 = p2.n3(wx * 0.055 + 33.3, y * 0.085 + 33.3, wz * 0.055 + 33.3);
            if (b2 > -0.10 && b2 < 0.10) id = 0;
          }
          if (id !== 0 && y < 26) {
            var ch2 = p2.n3(wx * 0.045 + 99.1, y * 0.06 + 99.1, wz * 0.045 + 99.1);
            if (ch2 > 0.58) id = 0;
          }
        }
        blocks[lidx(lx, y, lz)] = id;
      }
      // 海水
      for (var wy = h + 1; wy <= SEA; wy++) blocks[lidx(lx, wy, lz)] = ID.WATER;
      // 地表植被
      if (h > SEA && blocks[lidx(lx, h, lz)] === ID.GRASS) {
        var r = N.hash2(wx * 3 + 11, wz * 3 - 7);
        if (r < 0.10) blocks[lidx(lx, h + 1, lz)] = ID.TALLGRASS;
        else if (r < 0.113) blocks[lidx(lx, h + 1, lz)] = ID.DANDELION;
        else if (r < 0.126) blocks[lidx(lx, h + 1, lz)] = ID.POPPY;
      }
    }
    // 树木 / 仙人掌（含 2 格边距，树冠跨区块无缝）
    for (var tx = -2; tx < CH + 2; tx++) for (var tz = -2; tz < CH + 2; tz++) {
      var wx2 = cx * CH + tx, wz2 = cz * CH + tz;
      var th = treeAt(wx2, wz2);
      if (!th) continue;
      var h2 = heightAt(wx2, wz2);
      var biome2 = biomeOf(h2, tempAt(wx2, wz2), humidAt(wx2, wz2));
      if (biome2 === 'desert') {
        for (var k = 0; k < th; k++) setLocal(blocks, tx, h2 + 1 + k, tz, ID.CACTUS);
      } else {
        for (var k2 = 0; k2 < th; k2++) setLocal(blocks, tx, h2 + 1 + k2, tz, ID.LOG);
        var topY = h2 + th;
        for (var dy = -2; dy <= 1; dy++) {
          var rad = dy < 0 ? 2 : 1;
          for (var dx = -rad; dx <= rad; dx++) for (var dz = -rad; dz <= rad; dz++) {
            if (dx === 0 && dz === 0 && dy < 0) continue;
            if (Math.abs(dx) === rad && Math.abs(dz) === rad &&
                (dy >= 0 || N.hash3(wx2 + dx, topY + dy, wz2 + dz) < 0.5)) continue;
            setLocalIfAir(blocks, tx + dx, topY + dy, tz + dz, ID.LEAVES);
          }
        }
      }
    }
    var chunk = { cx: cx, cz: cz, blocks: blocks, dirty: true, modified: false };
    chunks.set(key(cx, cz), chunk);
    return chunk;
  }

  // ---------- 读写 ----------
  function getChunk(cx, cz) { return chunks.get(key(cx, cz)); }
  function hasChunk(cx, cz) { return chunks.has(key(cx, cz)); }
  function ensureChunk(cx, cz) { return chunks.get(key(cx, cz)) || generateChunk(cx, cz); }

  function getBlock(wx, wy, wz) {
    if (wy < 0 || wy >= H) return 0;
    var cx = Math.floor(wx / CH), cz = Math.floor(wz / CH);
    var c = chunks.get(key(cx, cz));
    if (!c) return 0;
    return c.blocks[lidx(wx - cx * CH, wy, wz - cz * CH)];
  }
  function isSolidAt(wx, wy, wz) {
    if (wy < 0 || wy >= H) return false;
    var cx = Math.floor(wx / CH), cz = Math.floor(wz / CH);
    var c = chunks.get(key(cx, cz));
    if (!c) return true; // 未加载区域视为实心，防止坠入
    return B.isSolid(c.blocks[lidx(wx - cx * CH, wy, wz - cz * CH)]);
  }
  function markDirty(cx, cz) {
    var c = chunks.get(key(cx, cz));
    if (c) c.dirty = true;
  }
  function setBlock(wx, wy, wz, id) {
    if (wy < 1 || wy >= H) return false;
    var cx = Math.floor(wx / CH), cz = Math.floor(wz / CH);
    var c = chunks.get(key(cx, cz));
    if (!c) return false;
    var lx = wx - cx * CH, lz = wz - cz * CH;
    c.blocks[lidx(lx, wy, lz)] = id;
    c.modified = true; c.dirty = true;
    if (lx === 0) markDirty(cx - 1, cz);
    if (lx === CH - 1) markDirty(cx + 1, cz);
    if (lz === 0) markDirty(cx, cz - 1);
    if (lz === CH - 1) markDirty(cx, cz + 1);
    return true;
  }
  function highestBlockY(wx, wz) {
    for (var y = H - 1; y >= 0; y--) {
      var id = getBlock(wx, y, wz);
      if (id !== 0 && !B.DEFS[id].water && !B.DEFS[id].cross) return y;
    }
    return -1;
  }

  // ---------- 存档（RLE 压缩已修改区块） ----------
  function rleEncode(bl) {
    var out = [], prev = bl[0], n = 1;
    for (var i = 1; i < bl.length; i++) {
      if (bl[i] === prev && n < 65535) n++;
      else { out.push(n, prev); prev = bl[i]; n = 1; }
    }
    out.push(n, prev);
    return out;
  }
  function rleDecode(arr) {
    var bl = new Uint8Array(CH * CH * H), p = 0;
    for (var i = 0; i < arr.length; i += 2) {
      var n = arr[i], id = arr[i + 1];
      while (n-- > 0) bl[p++] = id;
    }
    return bl;
  }
  function collectSave() {
    var cs = {};
    chunks.forEach(function (c) {
      if (c.modified) cs[c.cx + ',' + c.cz] = rleEncode(c.blocks);
    });
    return { seed: seed, chunks: cs };
  }
  function applySave(data) {
    init(data.seed);
    var cs = data.chunks || {};
    for (var k in cs) {
      var parts = k.split(',');
      var cx = +parts[0], cz = +parts[1];
      var chunk = { cx: cx, cz: cz, blocks: rleDecode(cs[k]), dirty: true, modified: true };
      chunks.set(key(cx, cz), chunk);
    }
  }
  function cleanupFar(pcx, pcz, keepR) {
    chunks.forEach(function (c, k) {
      if (c.modified) return;
      var d = Math.max(Math.abs(c.cx - pcx), Math.abs(c.cz - pcz));
      if (d > keepR) chunks.delete(k);
    });
  }

  return {
    init: init, getSeed: getSeed, key: key,
    heightAt: heightAt, biomeOf: biomeOf, tempAt: tempAt, humidAt: humidAt,
    getChunk: getChunk, hasChunk: hasChunk, ensureChunk: ensureChunk,
    getBlock: getBlock, isSolidAt: isSolidAt, setBlock: setBlock,
    highestBlockY: highestBlockY, collectSave: collectSave, applySave: applySave,
    cleanupFar: cleanupFar
  };
})();
","path":"js/world.js"}

{"content":"// 区块网格构建：面剔除 + 环境光遮蔽(AO) + 分层材质（实体/镂空/水）
window.WC = window.WC || {};
WC.mesher = (function () {
  var B = WC.blocks, ID = B.ID, C = WC.cfg;
  var CH = C.CHUNK, H = C.HEIGHT;
  var matOpaque, matCutout, matWater;

  function init(m) { matOpaque = m.opaque; matCutout = m.cutout; matWater = m.water; }

  // 面定义（顺序：-x,+x,-y,+y,-z,+z），角点 CCW 朝外
  var FACES = [
    { dir: [-1, 0, 0], shade: 0.78, corners: [
      { pos: [0, 1, 0], uv: [0, 1] }, { pos: [0, 0, 0], uv: [0, 0] },
      { pos: [0, 1, 1], uv: [1, 1] }, { pos: [0, 0, 1], uv: [1, 0] }] },
    { dir: [1, 0, 0], shade: 0.78, corners: [
      { pos: [1, 1, 1], uv: [0, 1] }, { pos: [1, 0, 1], uv: [0, 0] },
      { pos: [1, 1, 0], uv: [1, 1] }, { pos: [1, 0, 0], uv: [1, 0] }] },
    { dir: [0, -1, 0], shade: 0.55, corners: [
      { pos: [1, 0, 1], uv: [1, 0] }, { pos: [0, 0, 1], uv: [0, 0] },
      { pos: [1, 0, 0], uv: [1, 1] }, { pos: [0, 0, 0], uv: [0, 1] }] },
    { dir: [0, 1, 0], shade: 1.00, corners: [
      { pos: [0, 1, 1], uv: [1, 1] }, { pos: [1, 1, 1], uv: [0, 1] },
      { pos: [0, 1, 0], uv: [1, 0] }, { pos: [1, 1, 0], uv: [0, 0] }] },
    { dir: [0, 0, -1], shade: 0.88, corners: [
      { pos: [1, 0, 0], uv: [0, 0] }, { pos: [0, 0, 0], uv: [1, 0] },
      { pos: [1, 1, 0], uv: [0, 1] }, { pos: [0, 1, 0], uv: [1, 1] }] },
    { dir: [0, 0, 1], shade: 0.88, corners: [
      { pos: [0, 0, 1], uv: [0, 0] }, { pos: [1, 0, 1], uv: [1, 0] },
      { pos: [0, 1, 1], uv: [0, 1] }, { pos: [1, 1, 1], uv: [1, 1] }] }
  ];
  var AO_F = [0.45, 0.66, 0.84, 1.0];
  var INSET = 0.02;

  function tileU(ti, u) { return (((ti % 8) + u * (1 - 2 * INSET) + INSET) / 8); }
  function tileV(ti, vImg) {
    // vImg=1 为贴图顶部（flipY 纹理 v 大的一侧）
    var vv = 1 - ((((ti / 8) | 0) + (1 - vImg) * (1 - 2 * INSET) + INSET) / 8);
    return vv;
  }

  function makeGeo(a) {
    if (!a.idx.length) return null;
    var g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(a.pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(a.col, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(a.uv, 2));
    g.setIndex(a.idx);
    g.computeBoundingSphere();
    return g;
  }

  // chunk 需要周边 8 邻居均已生成
  function canMesh(cx, cz) {
    for (var dx = -1; dx <= 1; dx++) for (var dz = -1; dz <= 1; dz++)
      if (!WC.world.hasChunk(cx + dx, cz + dz)) return false;
    return true;
  }

  function build(chunk) {
    var cx = chunk.cx, cz = chunk.cz, blocks = chunk.blocks;
    var ox = cx * CH, oz = cz * CH;

    function getB(wx, wy, wz) {
      if (wy < 0 || wy >= H) return 0;
      var lx = wx - ox, lz = wz - oz;
      if (lx >= 0 && lx < CH && lz >= 0 && lz < CH) return blocks[(lx * CH + lz) * H + wy];
      return WC.world.getBlock(wx, wy, wz);
    }
    function opq(wx, wy, wz) { return B.isOpaque(getB(wx, wy, wz)); }

    var O = { pos: [], col: [], uv: [], idx: [] };
    var Cu = { pos: [], col: [], uv: [], idx: [] };
    var Wa = { pos: [], col: [], uv: [], idx: [] };

    function pushQuad(a, verts, flip) {
      var base = a.pos.length / 3;
      for (var i = 0; i < 4; i++) {
        a.pos.push(verts[i].x, verts[i].y, verts[i].z);
        a.col.push(verts[i].r, verts[i].r, verts[i].r);
        a.uv.push(verts[i].u, verts[i].v);
      }
      if (flip) a.idx.push(base + 1, base + 3, base, base, base + 3, base + 2);
      else a.idx.push(base, base + 1, base + 2, base + 2, base + 1, base + 3);
    }

    for (var lx = 0; lx < CH; lx++) for (var lz = 0; lz < CH; lz++) {
      var colBase = (lx * CH + lz) * H;
      for (var y = 0; y < H; y++) {
        var id = blocks[colBase + y];
        if (!id) continue;
        var d = B.DEFS[id];
        var wx = ox + lx, wz = oz + lz;

        if (d.cross) { // 花草交叉面片
          var ti = d.faces[0];
          var q = 0.07;
          var v1 = [
            { x: lx + q, y: y, z: lz + q, r: 1, u: tileU(ti, 0), v: tileV(ti, 0) },
            { x: lx + 1 - q, y: y, z: lz + 1 - q, r: 1, u: tileU(ti, 1), v: tileV(ti, 0) },
            { x: lx + q, y: y + 1, z: lz + q, r: 1, u: tileU(ti, 0), v: tileV(ti, 1) },
            { x: lx + 1 - q, y: y + 1, z: lz + 1 - q, r: 1, u: tileU(ti, 1), v: tileV(ti, 1) }];
          var v2 = [
            { x: lx + 1 - q, y: y, z: lz + q, r: 1, u: tileU(ti, 0), v: tileV(ti, 0) },
            { x: lx + q, y: y, z: lz + 1 - q, r: 1, u: tileU(ti, 1), v: tileV(ti, 0) },
            { x: lx + 1 - q, y: y + 1, z: lz + q, r: 1, u: tileU(ti, 0), v: tileV(ti, 1) },
            { x: lx + q, y: y + 1, z: lz + 1 - q, r: 1, u: tileU(ti, 1), v: tileV(ti, 1) }];
          pushQuad(Cu, v1, false); pushQuad(Cu, v2, false);
          continue;
        }

        var isWater = d.water;
        var target = isWater ? Wa : (d.cutout ? Cu : O);
        var topOpen = isWater && getB(wx, y + 1, wz) !== ID.WATER;

        for (var f = 0; f < 6; f++) {
          var F = FACES[f];
          var nx = wx + F.dir[0], ny = y + F.dir[1], nz = wz + F.dir[2];
          var nid = getB(nx, ny, nz);
          var nd = nid ? B.DEFS[nid] : null;
          var show;
          if (isWater) show = !nd || (!nd.opaque && !nd.water);
          else show = !nd || (!nd.opaque && nid !== id);
          if (!show) continue;

          var ti2 = d.faces[f];
          var verts = [], ao = [1, 1, 1, 1];

          if (!isWater) {
            // AO：基于面法线方向的两个切轴
            var axis = F.dir[0] !== 0 ? 0 : (F.dir[1] !== 0 ? 1 : 2);
            var t1 = axis === 0 ? 1 : 0;
            var t2 = axis === 2 ? 1 : 2;
            var bx = wx + F.dir[0], by = y + F.dir[1], bz = wz + F.dir[2];
          }
          var flip = false;

          for (var c = 0; c < 4; c++) {
            var co = F.corners[c];
            var py = co.pos[1];
            var yy = y + (isWater && py === 1 && topOpen ? 0.875 : py);
            var vv = { x: lx + co.pos[0], y: yy, z: lz + co.pos[2], r: F.shade, u: tileU(ti2, co.uv[0]), v: tileV(ti2, co.uv[1]) };

            if (!isWater) {
              var p = co.pos;
              var s1 = p[t1] === 1 ? 1 : -1;
              var s2 = p[t2] === 1 ? 1 : -1;
              var e1 = [0, 0, 0], e2 = [0, 0, 0];
              e1[t1] = s1; e2[t2] = s2;
              var o1 = opq(bx + e1[0], by + e1[1], bz + e1[2]) ? 1 : 0;
              var o2 = opq(bx + e2[0], by + e2[1], bz + e2[2]) ? 1 : 0;
              var oc = opq(bx + e1[0] + e2[0], by + e1[1] + e2[1], bz + e1[2] + e2[2]) ? 1 : 0;
              var lvl = (o1 && o2) ? 0 : 3 - (o1 + o2 + oc);
              ao[c] = AO_F[lvl];
              vv.r = F.shade * ao[c];
            }
            verts.push(vv);
          }
          if (!isWater) flip = (ao[0] + ao[3]) < (ao[1] + ao[2]);
          pushQuad(target, verts, flip);
        }
      }
    }

    var out = { opaque: null, cutout: null, water: null };
    var gO = makeGeo(O), gC = makeGeo(Cu), gW = makeGeo(Wa);
    if (gO) {
      out.opaque = new THREE.Mesh(gO, matOpaque);
      out.opaque.position.set(ox, 0, oz);
    }
    if (gC) {
      out.cutout = new THREE.Mesh(gC, matCutout);
      out.cutout.position.set(ox, 0, oz);
    }
    if (gW) {
      out.water = new THREE.Mesh(gW, matWater);
      out.water.position.set(ox, 0, oz);
      out.water.renderOrder = 2;
    }
    [out.opaque, out.cutout, out.water].forEach(function (m) {
      if (m) { m.matrixAutoUpdate = false; m.updateMatrix(); }
    });
    return out;
  }

  return { init: init, build: build, canMesh: canMesh };
})();
","path":"js/mesher.js"}

{"content":"// 体素射线检测（Amanatides & Woo DDA）
window.WC = window.WC || {};
WC.raycast = (function () {
  var B = WC.blocks;

  // test(id) → 是否命中；返回命中方块坐标、进入面法线与距离
  function cast(ox, oy, oz, dx, dy, dz, maxDist, test) {
    var x = Math.floor(ox), y = Math.floor(oy), z = Math.floor(oz);
    var stepX = dx > 0 ? 1 : -1, stepY = dy > 0 ? 1 : -1, stepZ = dz > 0 ? 1 : -1;
    var tdx = Math.abs(dx) < 1e-9 ? Infinity : Math.abs(1 / dx);
    var tdy = Math.abs(dy) < 1e-9 ? Infinity : Math.abs(1 / dy);
    var tdz = Math.abs(dz) < 1e-9 ? Infinity : Math.abs(1 / dz);
    var tmx = tdx === Infinity ? Infinity : (dx > 0 ? (x + 1 - ox) : (ox - x)) * tdx;
    var tmy = tdy === Infinity ? Infinity : (dy > 0 ? (y + 1 - oy) : (oy - y)) * tdy;
    var tmz = tdz === Infinity ? Infinity : (dz > 0 ? (z + 1 - oz) : (oz - z)) * tdz;
    var nx = 0, ny = 0, nz = 0, t = 0;

    for (var i = 0; i < 400; i++) {
      if (tmx < tmy && tmx < tmz) {
        x += stepX; t = tmx; tmx += tdx; nx = -stepX; ny = 0; nz = 0;
      } else if (tmy < tmz) {
        y += stepY; t = tmy; tmy += tdy; nx = 0; ny = -stepY; nz = 0;
      } else {
        z += stepZ; t = tmz; tmz += tdz; nx = 0; ny = 0; nz = -stepZ;
      }
      if (t > maxDist) return null;
      var id = WC.world.getBlock(x, y, z);
      if (test(id)) return { x: x, y: y, z: z, id: id, nx: nx, ny: ny, nz: nz, dist: t };
    }
    return null;
  }

  function blockTest(id) {
    return id !== 0 && !B.DEFS[id].water;
  }

  return { cast: cast, blockTest: blockTest };
})();
","path":"js/raycast.js"}

{"content":"// 天空：昼夜循环、太阳月亮星辰、云层、雨、光照
window.WC = window.WC || {};
WC.sky = (function () {
  var N = WC.noise;
  var scene, skyGroup, celestial, sun, moon, stars, cloudMesh, cloudMat;
  var ambient, sunLight;
  var dayF = 1, rainAmt = 0, rainTarget = 0;
  var angle = 0;
  var FOG_DIST = 100;

  function squareTex(paint) {
    var c = document.createElement('canvas'); c.width = c.height = 64;
    var ctx = c.getContext('2d');
    paint(ctx);
    var t = new THREE.CanvasTexture(c);
    t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter;
    return t;
  }

  function init(sc, renderDist) {
    scene = sc;
    FOG_DIST = renderDist * 1.15 * 16 / 16 * WC.cfg.RADIUS * 4; // ≈ RADIUS*16*1.15
    FOG_DIST = WC.cfg.RADIUS * 16 * 1.1;

    skyGroup = new THREE.Group();
    celestial = new THREE.Group();
    skyGroup.add(celestial);
    scene.add(skyGroup);

    var sunTex = squareTex(function (ctx) {
      ctx.fillStyle = '#fdf0a0'; ctx.fillRect(12, 12, 40, 40);
      ctx.fillStyle = '#fffde0'; ctx.fillRect(18, 18, 28, 28);
    });
    var moonTex = squareTex(function (ctx) {
      ctx.fillStyle = '#e2e6da'; ctx.fillRect(14, 14, 36, 36);
      ctx.fillStyle = '#c6ccbe'; ctx.fillRect(20, 22, 8, 8); ctx.fillRect(34, 34, 10, 7); ctx.fillRect(30, 18, 6, 5);
    });
    var sunMat = new THREE.MeshBasicMaterial({ map: sunTex, transparent: true, fog: false, depthWrite: false });
    var moonMat = new THREE.MeshBasicMaterial({ map: moonTex, transparent: true, fog: false, depthWrite: false });
    sun = new THREE.Mesh(new THREE.PlaneGeometry(70, 70), sunMat);
    moon = new THREE.Mesh(new THREE.PlaneGeometry(46, 46), moonMat);
    sun.position.set(400, 0, 0); moon.position.set(-400, 0, 0);
    sun.renderOrder = -9; moon.renderOrder = -9;
    celestial.add(sun); celestial.add(moon);

    // 星星
    var starGeo = new THREE.BufferGeometry();
    var sp = [], n = WC.noise.mulberry32(42);
    for (var i = 0; i < 450; i++) {
      var th = n() * Math.PI * 2, ph = Math.acos(n() * 2 - 1);
      var r = 420;
      sp.push(r * Math.sin(ph) * Math.cos(th), r * Math.cos(ph), r * Math.sin(ph) * Math.sin(th));
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(sp, 3));
    stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
      color: 0xcdd6ff, size: 1.6, sizeAttenuation: false, transparent: true, opacity: 0, fog: false, depthWrite: false
    }));
    stars.renderOrder = -10;
    celestial.add(stars);

    // 云（世界锚定贴图平移）
    var cCan = document.createElement('canvas'); cCan.width = cCan.height = 256;
    var cctx = cCan.getContext('2d');
    cctx.clearRect(0, 0, 256, 256);
    var cp = N.makePerlin(987654);
    for (var cy = 0; cy < 32; cy++) for (var cx = 0; cx < 32; cx++) {
      var v = N.fbm2(cp, cx * 0.28, cy * 0.28, 3);
      if (v > 0.12) { cctx.fillStyle = 'rgba(255,255,255,1)'; cctx.fillRect(cx * 8, cy * 8, 8, 8); }
    }
    cloudMat = new THREE.MeshBasicMaterial({
      map: new THREE.CanvasTexture(cCan), transparent: true, opacity: 0.55,
      depthWrite: false, side: THREE.DoubleSide, fog: false
    });
    cloudMat.map.wrapS = cloudMat.map.wrapT = THREE.RepeatWrapping;
    cloudMat.map.magFilter = THREE.NearestFilter; cloudMat.map.minFilter = THREE.NearestFilter;
    cloudMat.map.repeat.set(2, 2);
    cloudMesh = new THREE.Mesh(new THREE.PlaneGeometry(1024, 1024), cloudMat);
    cloudMesh.rotation.x = -Math.PI / 2;
    cloudMesh.position.y = 76;
    cloudMesh.renderOrder = -5;
    scene.add(cloudMesh);

    // 光照
    ambient = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambient);
    sunLight = new THREE.DirectionalLight(0xffffff, 1.0);
    scene.add(sunLight);
    scene.add(sunLight.target);

    scene.fog = new THREE.Fog(0x87ceeb, FOG_DIST * 0.55, FOG_DIST * 0.98);
    scene.background = new THREE.Color(0x87ceeb);
  }

  var C_DAY = new THREE.Color(0x84b3e8), C_NIGHT = new THREE.Color(0x0a0e24),
      C_DUSK = new THREE.Color(0xe0793f), C_RAINY = new THREE.Color(0x6f7d8f);
  var tmp = new THREE.Color(), tmp2 = new THREE.Color();

  function update(dt, px, py, pz, camera, time01, elapsed) {
    angle = time01 * Math.PI * 2 - Math.PI / 2;
    var sunH = Math.sin(angle);
    dayF = Math.max(0, Math.min(1, (sunH + 0.12) * 2.8));
    rainTarget = rainTarget; // set via setRain
    rainAmt += (rainTarget - rainAmt) * Math.min(1, dt * 1.5);

    celestial.rotation.z = angle;
    skyGroup.position.set(px, py, pz);

    sun.lookAt(camera.position);
    moon.lookAt(camera.position);
    var starOp = Math.max(0, Math.min(1, (-sunH + 0.06) * 3)) * (1 - rainAmt);
    stars.material.opacity = starOp;

    // 云：贴图随时间漂移 + 世界锚定
    var cellWorld = 512 / 2; // repeat 2 on 1024 plane → texture covers 512 units
    cloudMesh.position.x = px; cloudMesh.position.z = pz;
    cloudMat.map.offset.set(((px + elapsed * 3) / cellWorld) % 1, ((pz) / cellWorld) % 1);
    cloudMat.opacity = 0.5 + rainAmt * 0.4;

    // 颜色混合
    tmp.copy(C_NIGHT).lerp(C_DAY, dayF);
    var duskF = Math.max(0, 1 - Math.abs(sunH) * 5) * (0.35 + 0.4 * dayF);
    tmp.lerp(C_DUSK, duskF * 0.45);
    tmp2.copy(C_RAINY);
    tmp.lerp(tmp2, rainAmt * 0.65);
    scene.background.copy(tmp);
    scene.fog.color.copy(tmp);
    scene.fog.near = FOG_DIST * (0.55 - rainAmt * 0.35);
    scene.fog.far = FOG_DIST * (0.98 - rainAmt * 0.4);

    // 光照强度与方向
    var lightDir;
    if (sunH > -0.14) lightDir = new THREE.Vector3(Math.cos(angle), Math.sin(angle), 0.22).normalize();
    else lightDir = new THREE.Vector3(-Math.cos(angle), -Math.sin(angle), 0.22).normalize();
    sunLight.position.set(px + lightDir.x * 120, py + lightDir.y * 120 + 10, pz + lightDir.z * 120);
    sunLight.target.position.set(px, py, pz);
    var li = (sunH > -0.14 ? 0.25 + dayF * 0.85 : 0.14);
    sunLight.intensity = li * (1 - rainAmt * 0.55);
    sunLight.color.setRGB(1, 0.96 + 0.04 * dayF, 0.9 + 0.1 * dayF);
    ambient.intensity = (0.24 + 0.42 * dayF) * (1 - rainAmt * 0.3) + 0.02;
  }

  function setRain(on) { rainTarget = on ? 1 : 0; }
  function getDayLight() { return 0.3 + 0.7 * dayF * (1 - rainAmt * 0.4); }

  return { init: init, update: update, setRain: setRain, getDayLight: getDayLight };
})();
","path":"js/sky.js"}

{"content":"// 粒子：方块破坏碎屑 + 雨滴
window.WC = window.WC || {};
WC.particles = (function () {
  var B = WC.blocks;
  var scene, camera;
  var MAXP = 800;
  var pos, col, vel, life, count;
  var points, geo;
  var rain, rainGeo, rainDrops = 420, rainOn = false;
  var rainPos;

  function init(sc, cam) {
    scene = sc; camera = cam;
    geo = new THREE.BufferGeometry();
    pos = new Float32Array(MAXP * 3);
    col = new Float32Array(MAXP * 3);
    vel = new Float32Array(MAXP * 3);
    life = new Float32Array(MAXP);
    count = 0;
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setDrawRange(0, 0);
    points = new THREE.Points(geo, new THREE.PointsMaterial({
      size: 0.12, vertexColors: true, sizeAttenuation: true
    }));
    points.frustumCulled = false;
    scene.add(points);

    // 雨
    rainGeo = new THREE.BufferGeometry();
    rainPos = new Float32Array(rainDrops * 6);
    for (var i = 0; i < rainDrops; i++) {
      var x = (Math.random() - 0.5) * 40, y = Math.random() * 24, z = (Math.random() - 0.5) * 40;
      rainPos[i * 6] = x; rainPos[i * 6 + 1] = y; rainPos[i * 6 + 2] = z;
      rainPos[i * 6 + 3] = x; rainPos[i * 6 + 4] = y - 0.55; rainPos[i * 6 + 5] = z;
    }
    rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3).setUsage(THREE.DynamicDrawUsage));
    rain = new THREE.LineSegments(rainGeo, new THREE.LineBasicMaterial({
      color: 0x9db8d8, transparent: true, opacity: 0.38
    }));
    rain.frustumCulled = false;
    rain.visible = false;
    scene.add(rain);
  }

  function emitBlockBreak(x, y, z, id) {
    var c = B.avgColor(id);
    var n = Math.min(22, MAXP - count);
    for (var i = 0; i < n; i++) {
      var k = count++;
      var f = 0.65 + Math.random() * 0.55;
      pos[k * 3] = x + 0.15 + Math.random() * 0.7;
      pos[k * 3 + 1] = y + 0.15 + Math.random() * 0.7;
      pos[k * 3 + 2] = z + 0.15 + Math.random() * 0.7;
      vel[k * 3] = (Math.random() - 0.5) * 4;
      vel[k * 3 + 1] = 1.5 + Math.random() * 3.2;
      vel[k * 3 + 2] = (Math.random() - 0.5) * 4;
      col[k * 3] = c[0] * f; col[k * 3 + 1] = c[1] * f; col[k * 3 + 2] = c[2] * f;
      life[k] = 0.45 + Math.random() * 0.35;
    }
    geo.attributes.color.needsUpdate = true;
  }

  function update(dt, px, py, pz) {
    // 碎屑
    var dirty = false;
    for (var i = 0; i < count; i++) {
      life[i] -= dt;
      if (life[i] <= 0) {
        // swap-remove
        count--;
        for (var a = 0; a < 3; a++) {
          pos[i * 3 + a] = pos[count * 3 + a];
          col[i * 3 + a] = col[count * 3 + a];
          vel[i * 3 + a] = vel[count * 3 + a];
        }
        life[i] = life[count];
        i--; dirty = true;
        continue;
      }
      vel[i * 3 + 1] -= 16 * dt;
      pos[i * 3] += vel[i * 3] * dt;
      pos[i * 3 + 1] += vel[i * 3 + 1] * dt;
      pos[i * 3 + 2] += vel[i * 3 + 2] * dt;
      dirty = true;
    }
    if (dirty) {
      geo.attributes.position.needsUpdate = true;
      geo.attributes.color.needsUpdate = true;
    }
    geo.setDrawRange(0, count);

    // 雨
    rain.visible = rainOn;
    if (rainOn) {
      for (var d = 0; d < rainDrops; d++) {
        var oy = rainPos[d * 6 + 1];
        var ny = oy - 22 * dt;
        if (ny < py - 10) {
          ny = py + 14 + Math.random() * 8;
          var nx = px + (Math.random() - 0.5) * 44, nz = pz + (Math.random() - 0.5) * 44;
          rainPos[d * 6] = nx; rainPos[d * 6 + 2] = nz;
          rainPos[d * 6 + 3] = nx; rainPos[d * 6 + 5] = nz;
        }
        rainPos[d * 6 + 1] = ny;
        rainPos[d * 6 + 4] = ny - 0.55;
      }
      rainGeo.attributes.position.needsUpdate = true;
    }
  }

  function setRain(on) { rainOn = on; }

  return { init: init, emitBlockBreak: emitBlockBreak, update: update, setRain: setRain };
})();
","path":"js/particles.js"}

{"content":"// 程序化音效（WebAudio）：挖掘/放置/脚步/水/受伤 + 环境音乐
window.WC = window.WC || {};
WC.audio = (function () {
  var ctx = null, master, sfx, musicGain, rainGain;
  var musicTimer = null;
  var NOISE = null;

  function init() {
    if (ctx) return;
    try {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
    } catch (e) { return; }
    master = ctx.createGain(); master.gain.value = 0.55; master.connect(ctx.destination);
    sfx = ctx.createGain(); sfx.gain.value = 1; sfx.connect(master);
    musicGain = ctx.createGain(); musicGain.gain.value = 0.05; musicGain.connect(master);

    var len = ctx.sampleRate * 1.2;
    NOISE = ctx.createBuffer(1, len, ctx.sampleRate);
    var d = NOISE.getChannelData(0);
    for (var i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;

    startMusic();
    // 雨声循环
    var src = ctx.createBufferSource(); src.buffer = NOISE; src.loop = true;
    var lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 900;
    rainGain = ctx.createGain(); rainGain.gain.value = 0;
    src.connect(lp); lp.connect(rainGain); rainGain.connect(master);
    src.start();
  }

  function resume() { if (ctx && ctx.state === 'suspended') ctx.resume(); }

  function noiseHit(freq, dur, vol, type) {
    if (!ctx) return;
    var src = ctx.createBufferSource(); src.buffer = NOISE;
    var f = ctx.createBiquadFilter(); f.type = type || 'bandpass';
    f.frequency.value = freq; f.Q.value = 1.2;
    var g = ctx.createGain();
    var t = ctx.currentTime;
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(f); f.connect(g); g.connect(sfx);
    src.start(t); src.stop(t + dur + 0.05);
  }
  function tone(freq, dur, vol, type, slideTo) {
    if (!ctx) return;
    var o = ctx.createOscillator(); o.type = type || 'square';
    var t = ctx.currentTime;
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    var g = ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(sfx);
    o.start(t); o.stop(t + dur + 0.05);
  }

  var MAT_FREQ = { stone: 780, grass: 1250, wood: 480, sand: 1600, glass: 2300, snow: 1800, water: 600 };

  function dig(id) { noiseHit(MAT_FREQ[WC.blocks.DEFS[id].snd] || 800, 0.08, 0.25); }
  function breakSnd(id) {
    var f = MAT_FREQ[WC.blocks.DEFS[id].snd] || 800;
    noiseHit(f * 0.8, 0.18, 0.4);
    if (WC.blocks.DEFS[id].snd === 'glass') tone(1900, 0.15, 0.1, 'triangle', 900);
  }
  function place(id) { noiseHit((MAT_FREQ[WC.blocks.DEFS[id].snd] || 800) * 0.9, 0.1, 0.3); }
  function step(id) { noiseHit((MAT_FREQ[WC.blocks.DEFS[id].snd] || 800) * 1.1, 0.06, 0.11); }
  function splash() { noiseHit(620, 0.35, 0.4, 'lowpass'); noiseHit(1400, 0.2, 0.2); }
  function hurt() { tone(320, 0.22, 0.25, 'sawtooth', 130); }
  function click() { tone(820, 0.05, 0.12, 'square'); }
  function pop() { tone(520, 0.07, 0.14, 'sine', 780); }

  // ---- 环境音乐：柔和 pad 和弦 ----
  var CHORDS = [
    [261.63, 329.63, 392.00],  // C
    [220.00, 261.63, 329.63],  // Am
    [174.61, 220.00, 261.63],  // F
    [196.00, 246.94, 293.66]   // G
  ];
  var chordIdx = 0;
  function playChord() {
    if (!ctx) return;
    var ch = CHORDS[chordIdx % CHORDS.length];
    chordIdx += 1 + (Math.random() * 2 | 0);
    var t = ctx.currentTime;
    ch.forEach(function (f, i) {
      [0, 3.1].forEach(function (det) {
        var o = ctx.createOscillator();
        o.type = i === 0 ? 'sine' : 'triangle';
        o.frequency.value = f * (i === 0 ? 0.5 : 1);
        o.detune.value = det;
        var g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(0.09, t + 2.8);
        g.gain.linearRampToValueAtTime(0.0001, t + 8.4);
        var lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 900;
        o.connect(g); g.connect(lp); lp.connect(musicGain);
        o.start(t); o.stop(t + 8.6);
      });
    });
  }
  function startMusic() {
    if (musicTimer) return;
    playChord();
    musicTimer = setInterval(playChord, 8000);
  }

  function setRain(on) {
    if (!ctx) return;
    rainGain.gain.linearRampToValueAtTime(on ? 0.11 : 0, ctx.currentTime + 2);
  }

  return { init: init, resume: resume, dig: dig, breakSnd: breakSnd, place: place, step: step, splash: splash, hurt: hurt, click: click, pop: pop, setRain: setRain };
})();
","path":"js/audio.js"}

{"content":"// 手持视图：第一人称方块/手臂 + 摆动动画
window.WC = window.WC || {};
WC.viewmodel = (function () {
  var B = WC.blocks;
  var camera, group, blockMesh, armMesh, mat, armMat;
  var swingT = 1, bobPhase = 0, curId = -1;

  var BASE = { x: 0.52, y: -0.44, z: -0.72 };

  function init(cam) {
    camera = cam;
    group = new THREE.Group();
    camera.add(group);

    mat = new THREE.MeshBasicMaterial({ map: B.atlasTexture });
    armMat = new THREE.MeshBasicMaterial({ color: 0xd8a06c });

    blockMesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), mat);
    blockMesh.scale.setScalar(0.4);
    blockMesh.rotation.y = Math.PI / 6;
    blockMesh.visible = false;
    group.add(blockMesh);

    armMesh = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.75), armMat);
    armMesh.visible = false;
    group.add(armMesh);
  }

  function applyUV(id) {
    var d = B.DEFS[id];
    var g = blockMesh.geometry;
    var uv = g.attributes.uv;
    // BoxGeometry 面顺序: +x,-x,+y,-y,+z,-z
    var faceTile = [d.faces[0], d.faces[1], d.faces[2], d.faces[3], d.faces[4], d.faces[5]];
    for (var f = 0; f < 6; f++) {
      var ti = faceTile[f], tx = ti % 8, ty = (ti / 8) | 0;
      var base = f * 4;
      // 默认 uv 角序: (0,1),(1,1),(0,0),(1,0)
      var uvs = [[0, 1], [1, 1], [0, 0], [1, 0]];
      for (var v = 0; v < 4; v++) {
        var uu = (tx + uvs[v][0]) / 8;
        var vv = 1 - (ty + (1 - uvs[v][1])) / 8;
        uv.setXY(base + v, uu, vv);
      }
    }
    uv.needsUpdate = true;
  }

  function setBlock(id) {
    if (id === curId) return;
    curId = id;
    if (id === null || id === undefined || id === 0) {
      blockMesh.visible = false; armMesh.visible = true;
    } else {
      applyUV(id);
      blockMesh.visible = true; armMesh.visible = false;
    }
  }

  function swing() { if (swingT >= 1) swingT = 0; }

  function update(dt, opts) {
    opts = opts || {};
    if (swingT < 1) swingT = Math.min(1, swingT + dt / 0.24);
    var s = Math.sin(swingT * Math.PI);
    var bobAmp = (opts.moving && opts.onGround) ? 1 : 0;
    bobPhase += dt * (opts.speed || 0) * 1.7 * bobAmp;
    var bx = Math.sin(bobPhase) * 0.014 * bobAmp;
    var by = -Math.abs(Math.cos(bobPhase)) * 0.016 * bobAmp;

    group.position.set(BASE.x + bx, BASE.y + by - s * 0.1, BASE.z - s * 0.14);
    group.rotation.set(-s * 1.0, 0, 0);

    var l = 0.45 + 0.55 * (WC.sky ? WC.sky.getDayLight() : 1);
    mat.color.setScalar(Math.min(1, l));
    armMat.color.setRGB(0.85 * l, 0.63 * l, 0.42 * l);
  }

  return { init: init, setBlock: setBlock, swing: swing, update: update };
})();
","path":"js/viewmodel.js"}

{"content":"// 玩家：物理碰撞、移动、生命/饥饿、水中泳动、创造/生存模式
window.WC = window.WC || {};
WC.player = (function () {
  var C = WC.cfg, B = WC.blocks, W = WC.world;
  var ID = B.ID;

  var pos = { x: 0, y: 0, z: 0 };
  var vel = { x: 0, y: 0, z: 0 };
  var yaw = 0, pitch = 0;
  var onGround = false, inWater = false, headInWater = false;
  var sprinting = false, sneaking = false, flying = false;
  var hp = 20, hunger = 20, air = 10;
  var regenT = 0, hungerT = 0, fallStart = null, lastDamageT = 0;
  var stepDist = 0;
  var creative = false;
  var lastStepTime = 0;

  function solidBoxCollide(px, py, pz) {
    var x0 = Math.floor(px - C.PW), x1 = Math.floor(px + C.PW);
    var y0 = Math.floor(py), y1 = Math.floor(py + C.PH);
    var z0 = Math.floor(pz - C.PW), z1 = Math.floor(pz + C.PW);
    for (var x = x0; x <= x1; x++)
      for (var y = y0; y <= y1; y++)
        for (var z = z0; z <= z1; z++)
          if (W.isSolidAt(x, y, z)) return true;
    return false;
  }

  function waterBox(px, py, pz, eyeOffset) {
    var x0 = Math.floor(px - C.PW), x1 = Math.floor(px + C.PW);
    var y0 = Math.floor(py), y1 = Math.floor(py + C.PH * 0.7);
    var z0 = Math.floor(pz - C.PW), z1 = Math.floor(pz + C.PW);
    var n = 0;
    for (var x = x0; x <= x1; x++)
      for (var y = y0; y <= y1; y++)
        for (var z = z0; z <= z1; z++)
          if (W.getBlock(x, y, z) === ID.WATER) n++;
    return n;
  }

  function collideMove(dx, dy, dz) {
    // 分轴移动 + 基于速度步长的扫掠
    var steps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) / 0.2));
    var sx = dx / steps, sy = dy / steps, sz = dz / steps;
    for (var i = 0; i < steps; i++) {
      if (sx !== 0) {
        if (!solidBoxCollide(pos.x + sx, pos.y, pos.z)) pos.x += sx;
        else { vel.x = 0; sx = 0; }
      }
      if (sz !== 0) {
        if (!solidBoxCollide(pos.x, pos.y, pos.z + sz)) pos.z += sz;
        else { vel.z = 0; sz = 0; }
      }
      if (sy !== 0) {
        if (!solidBoxCollide(pos.x, pos.y + sy, pos.z)) pos.y += sy;
        else {
          if (sy < 0) {
            if (!onGround) { onGround = true; landed(); }
          }
          vel.y = 0; sy = 0;
        }
      }
    }
  }

  function landed() {
    if (fallStart !== null && !creative) {
      var fall = fallStart - pos.y;
      if (fall > 3.5 && !inWater) {
        var dmg = Math.floor(fall - 3);
        if (dmg > 0) damage(dmg, '坠落');
      }
    }
    fallStart = null;
  }

  function damage(n, why) {
    var t = performance.now() / 1000;
    if (t - lastDamageT < 0.45) return;
    lastDamageT = t;
    hp = Math.max(0, hp - n);
    WC.audio.hurt();
    WC.hud.flashVignette();
    if (hp <= 0) die(why);
  }

  function die(why) {
    WC.main.onPlayerDeath(why || '死亡');
  }

  function respawn() {
    hp = 20; hunger = 20; air = 10;
    vel.x = vel.y = vel.z = 0;
    fallStart = null;
    var sp = WC.main.findSpawn();
    pos.x = sp.x; pos.y = sp.y; pos.z = sp.z;
  }

  function eyeHeight() { return sneaking ? C.EYE_SNEAK : C.EYE; }

  function update(dt, input, camera) {
    var speedTarget = flying ? (input.sprint ? C.FLY_SPRINT : C.FLY)
      : input.sprint ? C.SPRINT : (input.sneak ? C.SNEAK : C.WALK);
    if (inWater && !flying) speedTarget *= 0.55;
    if (sneaking && onGround && !flying) speedTarget = C.SNEAK;

    var wasGround = onGround;
    onGround = false;

    // 期望水平速度
    var fw = (input.forward ? 1 : 0) - (input.back ? 1 : 0);
    var st = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    var len = Math.hypot(fw, st) || 1;
    var sin = Math.sin(yaw), cos = Math.cos(yaw);
    var wishX = (-sin * fw / len + cos * st / len) * speedTarget;
    var wishZ = (-cos * fw / len - sin * st / len) * speedTarget;

    var accel = onGround || flying ? 14 : 4.5;
    vel.x += (wishX - vel.x) * Math.min(1, accel * dt);
    vel.z += (wishZ - vel.z) * Math.min(1, accel * dt);

    // 垂直
    if (flying) {
      var wy = (input.jump ? 1 : 0) - (input.sneak ? 1 : 0);
      vel.y += (wy * speedTarget - vel.y) * Math.min(1, 12 * dt);
    } else if (inWater) {
      vel.y -= 5.5 * dt;
      if (input.jump) vel.y = Math.min(vel.y + 24 * dt, 3.6);
      vel.y *= Math.pow(0.9, dt * 60);
    } else {
      vel.y -= C.GRAVITY * dt;
      if (input.jump && onGround) {
        vel.y = C.JUMP;
        onGround = false;
      }
    }

    // 疾跑判断（前进+同向按键）
    if (input.sprint && fw <= 0 && !flying) sprinting = false;

    var oldY = pos.y;
    if (fallStart === null && !onGround && vel.y < -0.1 && !flying && !inWater) fallStart = pos.y;
    if (flying || inWater) fallStart = null;

    collideMove(vel.x * dt, vel.y * dt, vel.z * dt);

    if (!wasGround && onGround && !creative) { /* landed() 已处理 */ }

    // 保险：卡进方块时上推
    var tries = 0;
    while (solidBoxCollide(pos.x, pos.y, pos.z) && tries++ < 50) pos.y += 0.05;

    // 水检测
    var wn = waterBox(pos.x, pos.y, pos.z);
    var wasIn = inWater;
    inWater = wn >= 4;
    headInWater = W.getBlock(Math.floor(pos.x), Math.floor(pos.y + eyeHeight()), Math.floor(pos.z)) === ID.WATER;
    if (!wasIn && inWater && vel.y < -3) WC.audio.splash();

    // 脚步声
    var spd = Math.hypot(vel.x, vel.z);
    if (onGround && spd > 1.4) {
      stepDist += spd * dt;
      if (stepDist > 2.1) {
        stepDist = 0;
        var under = W.getBlock(Math.floor(pos.x), Math.floor(pos.y - 0.5), Math.floor(pos.z));
        if (under) WC.audio.step(under);
      }
    }

    // 生存模式：饥饿/回血/溺水
    if (!creative) {
      hungerT += dt;
      if (hungerT > 28) {
        hungerT = 0;
        hunger = Math.max(0, hunger - 1);
      }
      if (hunger > 17 && hp < 20) {
        regenT += dt;
        if (regenT > C.REGEN_TIME) { regenT = 0; hp = Math.min(20, hp + 1); }
      }
      if (headInWater) {
        air -= dt;
        if (air < 0) { air = 1; damage(2, '溺水'); }
      } else air = Math.min(10, air + dt * 3);
    }

    // 相机
    camera.position.set(pos.x, pos.y + eyeHeight(), pos.z);
    camera.rotation.order = 'YXZ';
    camera.rotation.y = yaw;
    camera.rotation.x = pitch;
  }

  function addYaw(d) { yaw -= d; }
  function addPitch(d) {
    pitch -= d;
    pitch = Math.max(-Math.PI / 2 + 0.001, Math.min(Math.PI / 2 - 0.001, pitch));
  }
  function toggleFly() {
    flying = !flying;
    vel.y = 0;
    return flying;
  }

  return {
    pos: pos, vel: vel,
    get yaw() { return yaw; }, set yaw(v) { yaw = v; },
    get pitch() { return pitch; }, set pitch(v) { pitch = v; },
    get onGround() { return onGround; },
    get inWater() { return inWater; },
    get headInWater() { return headInWater; },
    get flying() { return flying; },
    get hp() { return hp; }, get hunger() { return hunger; }, get air() { return air; },
    get creative() { return creative; }, set creative(v) { creative = v; },
    update: update, addYaw: addYaw, addPitch: addPitch, toggleFly: toggleFly,
    damage: damage, respawn: respawn, eyeHeight: eyeHeight,
    setSpawn: function (x, y, z) { pos.x = x; pos.y = y; pos.z = z; }
  };
})();
","path":"js/player.js"}

{"content":"// HUD：快捷栏、心/饥饿/气泡、Toast、调试信息、物品栏
window.WC = window.WC || {};
WC.hud = (function () {
  var B = WC.blocks;
  var el = {};
  var hotbar = [B.ID.GRASS, B.ID.DIRT, B.ID.STONE, B.ID.COBBLE, B.ID.PLANKS,
                B.ID.LOG, B.ID.LEAVES, B.ID.GLASS, B.ID.GLOWSTONE];
  var sel = 0;
  var toastTimer = null;
  var vigFlash = 0;

  function heartSVG(fill) {
    return '<svg viewBox="0 0 9 9" width="18" height="18"><path d="M1 2h2v1h1v1h1V3h1V2h2v1h1v2h-1v1h-1v1H7v1H6v1H5v1H4V9H3V8H2V7H1V6H0V5H-0z" fill="none"/><path d="M2 1h2v1h1V1h2v1h1v3h-1v1h-1v1H5v1H4V7H3V6H2V5H1V2h1z" fill="' + (fill ? '#e8342c' : '#3a0c0a') + '"/></svg>';
  }
  function drumSVG(fill) {
    return '<svg viewBox="0 0 9 9" width="18" height="18"><path d="M2 1h5v1h1v4h-1v2H2V8H1V6H0V2h1V1h1z" fill="' + (fill ? '#c78346' : '#3a2314') + '"/><path d="M2 2h4v1h1v2H6v2H2V6H1V3h1z" fill="' + (fill ? '#e8a45c' : '#4a2c18') + '" opacity="' + (fill ? 1 : 0.7) + '"/></svg>';
  }
  function bubbleSVG() {
    return '<svg viewBox="0 0 9 9" width="18" height="18"><circle cx="4.5" cy="4.5" r="3.4" fill="#2e64c8" stroke="#bcd4ff" stroke-width="0.8"/><circle cx="3.4" cy="3.4" r="1" fill="#dceaff"/></svg>';
  }

  function init() {
    ['hud', 'hearts', 'hunger', 'bubbles', 'hotbar', 'toast', 'debug',
     'inventory', 'invGrid', 'vignette', 'waterOverlay', 'menu', 'pause', 'death',
     'seedLine', 'logo', 'splash'].forEach(function (id) { el[id] = document.getElementById(id); });

    for (var i = 0; i < 9; i++) {
      var s = document.createElement('div');
      s.className = 'slot' + (i === 0 ? ' sel' : '');
      s.dataset.idx = i;
      el.hotbar.appendChild(s);
    }
    renderHotbar();
    renderStatus({ hp: 20, hunger: 20, air: 10 });
    buildInventory();
  }

  function renderHotbar() {
    var slots = el.hotbar.children;
    for (var i = 0; i < 9; i++) {
      var s = slots[i];
      s.classList.toggle('sel', i === sel);
      var id = hotbar[i];
      s.innerHTML = (id ? '<img draggable="false" src="' + B.DEFS[id].icon + '">' : '') +
        '<span class="num">' + (i + 1) + '</span>';
    }
  }

  function buildInventory() {
    var g = el.invGrid;
    g.innerHTML = '';
    B.PLACEABLE.forEach(function (id) {
      var d = document.createElement('div');
      d.className = 'inv-slot';
      d.title = B.DEFS[id].name;
      d.innerHTML = '<img draggable="false" src="' + B.DEFS[id].icon + '">';
      d.addEventListener('click', function () {
        hotbar[sel] = id;
        renderHotbar();
        WC.audio.pop();
        hideInventory();
      });
      g.appendChild(d);
    });
  }

  function showInventory() { el.inventory.classList.remove('hidden'); }
  function hideInventory() { el.inventory.classList.add('hidden'); }
  function inventoryOpen() { return !el.inventory.classList.contains('hidden'); }

  function renderStatus(st) {
    var h = '';
    for (var i = 0; i < 10; i++) h += heartSVG(st.hp >= (i + 1) * 2);
    el.hearts.innerHTML = h;
    var f = '';
    for (var j = 0; j < 10; j++) f += drumSVG(st.hunger >= (j + 1) * 2);
    el.hunger.innerHTML = f;
    var b = '';
    if (st.air < 10) {
      var nb = Math.ceil(st.air);
      for (var k = 0; k < nb; k++) b += bubbleSVG();
    }
    el.bubbles.innerHTML = b;
    var hidden = WC.player && WC.player.creative;
    el.hearts.parentNode.style.opacity = hidden ? 0 : 1;
  }

  function setHotbarSel(i) {
    sel = ((i % 9) + 9) % 9;
    renderHotbar();
  }
  function currentBlock() { return hotbar[sel]; }
  function scrollSel(d) { setHotbarSel(sel + d); }

  function toast(msg) {
    el.toast.textContent = msg;
    el.toast.style.opacity = 1;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.toast.style.opacity = 0; }, 1400);
  }

  function flashVignette() { vigFlash = 1; }

  function setWaterOverlay(on) { el.waterOverlay.style.opacity = on ? 1 : 0; }

  function update(dt, player) {
    if (vigFlash > 0) {
      vigFlash = Math.max(0, vigFlash - dt * 2.2);
      el.vignette.style.opacity = vigFlash;
    }
    renderStatus({ hp: player.hp, hunger: player.hunger, air: player.air });
  }

  function debug(info) {
    el.debug.textContent = info;
  }
  function toggleDebug() { el.debug.classList.toggle('hidden'); }

  return {
    init: init, renderHotbar: renderHotbar, setHotbarSel: setHotbarSel,
    scrollSel: scrollSel, currentBlock: currentBlock,
    showInventory: showInventory, hideInventory: hideInventory, inventoryOpen: inventoryOpen,
    toast: toast, flashVignette: flashVignette, setWaterOverlay: setWaterOverlay,
    update: update, debug: debug, toggleDebug: toggleDebug,
    hotbar: hotbar, el: el
  };
})();
","path":"js/hud.js"}

{"content":"// 主入口：渲染循环、区块调度、输入、交互、存档、菜单
window.addEventListener('error', function (e) { document.title = 'WC-ERR ' + e.message; });

WC.main = (function () {
  var C = WC.cfg, B = WC.blocks, W = WC.world, M = WC.mesher, R = WC.raycast;
  var renderer, scene, camera;
  var canvas = document.getElementById('game');
  var state = 'menu'; // menu | playing | paused | dead | inventory
  var matOpaque, matCutout, matWater;
  var chunkMeshes = new Map();
  var highlight, crackMesh, crackMat;
  var mining = false, mineKey = null, mineProgress = 0, digSndT = 0;
  var placing = false, placeT = 0;
  var input = { forward: false, back: false, left: false, right: false, jump: false, sneak: false, sprint: false };
  var lastW = -10, lastSpace = -10;
  var timeOfDay = 0.30, elapsed = 0;
  var weatherT = 50, raining = false;
  var stats = { mined: 0, placed: 0 };
  var fovBase = 75;
  var fps = 60, saveT = 0, cleanupT = 0;
  var debugOn = false;
  var tmpV = null;
  var menuOrbit = 0;
  var started = false;
  var lastVM = -1;
  var AUTOSTART = location.search.indexOf('autostart') >= 0;

  function $(id) { return document.getElementById(id); }

  // ---------------- 初始化 ----------------
  function init() {
    tmpV = new THREE.Vector3();
    renderer = new THREE.WebGLRenderer({
      canvas: canvas, antialias: false, powerPreference: 'high-performance',
      preserveDrawingBuffer: AUTOSTART
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    renderer.setSize(window.innerWidth, window.innerHeight);
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(fovBase, window.innerWidth / window.innerHeight, 0.08, 1200);
    scene.add(camera);

    matOpaque = new THREE.MeshBasicMaterial({ map: B.atlasTexture, vertexColors: true });
    matCutout = new THREE.MeshBasicMaterial({ map: B.atlasTexture, vertexColors: true, transparent: true, alphaTest: 0.45, side: THREE.DoubleSide });
    matWater = new THREE.MeshBasicMaterial({ map: B.atlasTexture, vertexColors: true, transparent: true, opacity: 0.72, depthWrite: false, side: THREE.DoubleSide });
    M.init({ opaque: matOpaque, cutout: matCutout, water: matWater });

    WC.sky.init(scene);
    WC.particles.init(scene, camera);
    WC.hud.init();
    WC.viewmodel.init(camera);

    highlight = new THREE.LineSegments(
      new THREE.EdgesGeometry(new THREE.BoxGeometry(1.002, 1.002, 1.002)),
      new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.55 }));
    highlight.visible = false;
    scene.add(highlight);

    crackMat = new THREE.MeshBasicMaterial({ map: B.crackTex[0], transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
    crackMesh = new THREE.Mesh(new THREE.BoxGeometry(1.001, 1.001, 1.001), crackMat);
    crackMesh.visible = false;
    crackMesh.renderOrder = 3;
    scene.add(crackMesh);

    var splashes = ['网页版！', '也是 100% 方块！', 'Three.js 驱动！', '无限世界！', '有钻石！', '试试创造模式！', '小心洞穴！', '纯浏览器运行！'];
    $('splash').textContent = splashes[(Math.random() * splashes.length) | 0];

    initWorldOrMenu();
    bindEvents();
    requestAnimationFrame(loop);
  }

  function newSeed() { return (Math.random() * 0x7fffffff) | 0; }

  function initWorldOrMenu() {
    var data = null;
    try {
      var raw = localStorage.getItem(C.SAVE_KEY);
      if (raw) data = JSON.parse(raw);
    } catch (e) { data = null; }
    if (data && data.v === 1 && data.world) {
      W.applySave(data.world);
      timeOfDay = data.time || 0.3;
      raining = !!data.rain;
      stats = data.stats || { mined: 0, placed: 0 };
      var P = WC.player, p = data.player || {};
      P.setSpawn(p.x || 0, p.y || 40, p.z || 0);
      P.yaw = p.yaw || 0; P.pitch = p.pitch || 0;
      P.creative = !!p.creative;
      if (Array.isArray(data.hotbar) && data.hotbar.length === 9) {
        for (var i = 0; i < 9; i++) WC.hud.hotbar[i] = data.hotbar[i];
      }
      WC.hud.setHotbarSel(data.sel || 0);
      $('btnStart').textContent = '继续游戏';
    } else {
      W.init(newSeed());
      var sp = findSpawn();
      WC.player.setSpawn(sp.x, sp.y, sp.z);
      WC.player.yaw = Math.PI * 0.25;
    }
    $('seedLine').textContent = '种子：' + W.getSeed() + (data ? '（检测到存档）' : '');
    WC.sky.setRain(raining);
  }

  function findSpawn() {
    for (var r = 0; r <= 220; r += 6) {
      for (var a = 0; a < 12; a++) {
        var ang = a * Math.PI / 6;
        var x = Math.round(Math.cos(ang) * r), z = Math.round(Math.sin(ang) * r);
        var h = W.heightAt(x, z);
        if (h > C.SEA + 1 && h < C.SNOWLINE) return { x: x + 0.5, y: h + 1.02, z: z + 0.5 };
      }
    }
    return { x: 0.5, y: C.SEA + 8, z: 0.5 };
  }

  // ---------------- 状态切换 ----------------
  function startGame() {
    WC.audio.init(); WC.audio.resume();
    WC.audio.setRain(raining);
    WC.audio.click();
    state = 'playing';
    started = true;
    $('menu').classList.add('hidden');
    $('pause').classList.add('hidden');
    $('death').classList.add('hidden');
    WC.hud.el.hud.classList.remove('hidden');
    if (!AUTOSTART) lockPointer();
  }
  function lockPointer() { canvas.requestPointerLock(); }

  function pauseGame() {
    if (state !== 'playing') return;
    state = 'paused';
    $('pause').classList.remove('hidden');
    saveNow();
  }
  function resumeGame() {
    if (state !== 'paused') return;
    WC.audio.click();
    $('pause').classList.add('hidden');
    state = 'playing';
    lockPointer();
  }
  function onPlayerDeath(why) {
    state = 'dead';
    document.exitPointerLock();
    mining = false; placing = false;
    $('deathScore').textContent = '原因：' + why + ' · 生存 ' + Math.floor(elapsed / C.DAY_LENGTH) + ' 天 · 挖掘 ' + stats.mined + ' · 放置 ' + stats.placed;
    $('death').classList.remove('hidden');
  }
  function respawn() {
    WC.audio.click();
    $('death').classList.add('hidden');
    WC.player.respawn();
    state = 'playing';
    lockPointer();
  }
  function resetWorld() {
    WC.audio.click();
    try { localStorage.removeItem(C.SAVE_KEY); } catch (e) {}
    chunkMeshes.forEach(function (m) { disposeChunk(m); });
    chunkMeshes.clear();
    W.init(newSeed());
    WC.player.respawn();
    WC.player.creative = false;
    timeOfDay = 0.3; elapsed = 0; stats = { mined: 0, placed: 0 };
    raining = false; WC.sky.setRain(false); WC.audio.setRain(false);
    $('seedLine').textContent = '种子：' + W.getSeed();
    $('btnStart').textContent = '开始游戏';
    WC.hud.toast('已生成新世界');
  }

  var HELP = '鼠标 — 视角｜左键 挖掘｜右键 放置｜中键 取方块<br>' +
    'WASD — 移动｜空格 — 跳跃｜Shift — 潜行｜双击 W — 疾跑<br>' +
    '滚轮 / 1-9 — 切换快捷栏｜E — 物品栏｜G — 创造/生存切换<br>' +
    '创造模式下双击空格 — 飞行（空格升 / Shift 降）<br>' +
    'F3 — 调试信息｜Esc — 暂停';

  // ---------------- 区块调度 ----------------
  function buildChunkMesh(c) {
    var k = W.key(c.cx, c.cz);
    var old = chunkMeshes.get(k);
    if (old) disposeChunk(old);
    var m = M.build(c);
    m.cx = c.cx; m.cz = c.cz;
    if (m.opaque) scene.add(m.opaque);
    if (m.cutout) scene.add(m.cutout);
    if (m.water) scene.add(m.water);
    chunkMeshes.set(k, m);
    c.dirty = false;
  }
  function disposeChunk(m) {
    ['opaque', 'cutout', 'water'].forEach(function (k) {
      if (m[k]) { scene.remove(m[k]); m[k].geometry.dispose(); }
    });
  }
  function pumpChunks(genBudget, meshBudget) {
    var P = WC.player.pos;
    var pcx = Math.floor(P.x / C.CHUNK), pcz = Math.floor(P.z / C.CHUNK);
    var R1 = C.RADIUS + 1, gens = [];
    for (var dx = -R1; dx <= R1; dx++) for (var dz = -R1; dz <= R1; dz++)
      if (!W.hasChunk(pcx + dx, pcz + dz)) gens.push([dx * dx + dz * dz, dx, dz]);
    gens.sort(function (a, b) { return a[0] - b[0]; });
    var i, n;
    for (i = 0, n = Math.min(genBudget, gens.length); i < n; i++)
      W.ensureChunk(pcx + gens[i][1], pcz + gens[i][2]);

    var need = [];
    for (dx = -C.RADIUS; dx <= C.RADIUS; dx++) for (dz = -C.RADIUS; dz <= C.RADIUS; dz++) {
      var c = W.getChunk(pcx + dx, pcz + dz);
      if (c && c.dirty && M.canMesh(c.cx, c.cz)) need.push([dx * dx + dz * dz, c]);
    }
    need.sort(function (a, b) { return a[0] - b[0]; });
    for (i = 0, n = Math.min(meshBudget, need.length); i < n; i++) buildChunkMesh(need[i][1]);
  }
  function removeFarMeshes() {
    var P = WC.player.pos;
    var pcx = Math.floor(P.x / C.CHUNK), pcz = Math.floor(P.z / C.CHUNK);
    var kill = [];
    chunkMeshes.forEach(function (m, k) {
      if (Math.max(Math.abs(m.cx - pcx), Math.abs(m.cz - pcz)) > C.RADIUS + 1) kill.push(k);
    });
    for (var i = 0; i < kill.length; i++) {
      disposeChunk(chunkMeshes.get(kill[i]));
      chunkMeshes.delete(kill[i]);
    }
    W.cleanupFar(pcx, pcz, C.RADIUS + 3);
  }
  function rebuildDirtyNow() {
    var P = WC.player.pos;
    var pcx = Math.floor(P.x / C.CHUNK), pcz = Math.floor(P.z / C.CHUNK);
    for (var dx = -1; dx <= 1; dx++) for (var dz = -1; dz <= 1; dz++) {
      var c = W.getChunk(pcx + dx, pcz + dz);
      if (c && c.dirty && chunkMeshes.has(W.key(c.cx, c.cz))) buildChunkMesh(c);
    }
  }

  // ---------------- 交互 ----------------
  function getTarget() {
    camera.getWorldDirection(tmpV);
    var e = camera.position;
    return R.cast(e.x, e.y, e.z, tmpV.x, tmpV.y, tmpV.z, C.REACH, R.blockTest);
  }
  function playerOverlaps(bx, by, bz) {
    var P = WC.player, p = P.pos;
    return bx + 1 > p.x - C.PW && bx < p.x + C.PW &&
           by + 1 > p.y && by < p.y + C.PH &&
           bz + 1 > p.z - C.PW && bz < p.z + C.PW;
  }
  function tryPlace(hit) {
    var id = WC.hud.currentBlock();
    if (!id) return;
    var px = hit.x + hit.nx, py = hit.y + hit.ny, pz = hit.z + hit.nz;
    if (py < 1 || py >= C.HEIGHT) return;
    var cur = W.getBlock(px, py, pz);
    if (cur !== 0 && !B.isReplaceable(cur)) return;
    if (B.DEFS[id].solid && playerOverlaps(px, py, pz)) return;
    if (W.setBlock(px, py, pz, id)) {
      rebuildDirtyNow();
      WC.audio.place(id);
      stats.placed++;
      WC.viewmodel.swing();
    }
  }
  function updateMining(dt, hit) {
    if (!mining || !hit || state !== 'playing') {
      mineKey = null; mineProgress = 0; crackMesh.visible = false;
      return;
    }
    var k = hit.x + ',' + hit.y + ',' + hit.z;
    if (mineKey !== k) { mineKey = k; mineProgress = 0; }
    var def = B.DEFS[hit.id];
    if (def.hard === Infinity) { crackMesh.visible = false; return; }
    mineProgress += dt / (WC.player.creative ? 0.12 : def.hard);
    digSndT -= dt;
    if (digSndT <= 0) { WC.audio.dig(hit.id); digSndT = 0.22; WC.viewmodel.swing(); }
    if (mineProgress >= 1) {
      W.setBlock(hit.x, hit.y, hit.z, 0);
      var above = W.getBlock(hit.x, hit.y + 1, hit.z);
      if (above && B.DEFS[above].cross) W.setBlock(hit.x, hit.y + 1, hit.z, 0);
      rebuildDirtyNow();
      WC.particles.emitBlockBreak(hit.x, hit.y, hit.z, hit.id);
      WC.audio.breakSnd(hit.id);
      stats.mined++;
      mineKey = null; mineProgress = 0;
      crackMesh.visible = false;
      return;
    }
    crackMesh.visible = true;
    crackMesh.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5);
    crackMat.map = B.crackTex[Math.min(9, (mineProgress * 10) | 0)];
  }
  function handleInteraction(dt) {
    var hit = getTarget();
    if (hit) {
      highlight.visible = true;
      highlight.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5);
    } else highlight.visible = false;
    updateMining(dt, hit);
    if (placing) {
      placeT -= dt;
      if (placeT <= 0) { placeT = 0.22; if (hit) tryPlace(hit); }
    }
  }

  // ---------------- 输入 ----------------
  function openInventory() {
    state = 'inventory';
    document.exitPointerLock();
    WC.hud.showInventory();
    mining = false; placing = false;
  }
  function closeInventory() {
    WC.hud.hideInventory();
    state = 'playing';
    lockPointer();
  }
  function toggleCreative() {
    var P = WC.player;
    P.creative = !P.creative;
    if (!P.creative && P.flying) P.toggleFly();
    WC.hud.toast(P.creative ? '创造模式（双击空格飞行）' : '生存模式');
    WC.audio.pop();
  }
  function onKey(e) {
    var down = e.type === 'keydown';
    if (e.code === 'F3') { e.preventDefault(); if (down) { debugOn = !debugOn; WC.hud.toggleDebug(); } return; }
    if (down && e.code === 'KeyE') {
      if (state === 'playing') openInventory();
      else if (state === 'inventory') closeInventory();
      return;
    }
    if (down && e.code === 'Escape' && state === 'inventory') { closeInventory(); return; }
    if (state !== 'playing') return;
    switch (e.code) {
      case 'KeyW':
        if (down && !input.forward) {
          var now = performance.now() / 1000;
          if (now - lastW < 0.28) input.sprint = true;
          lastW = now;
        }
        if (!down) input.sprint = false;
        input.forward = down; break;
      case 'KeyS': input.back = down; break;
      case 'KeyA': input.left = down; break;
      case 'KeyD': input.right = down; break;
      case 'ShiftLeft': case 'ShiftRight': input.sneak = down; break;
      case 'Space':
        if (down && !input.jump) {
          var now2 = performance.now() / 1000;
          if (now2 - lastSpace < 0.28 && WC.player.creative) {
            WC.hud.toast(WC.player.toggleFly() ? '飞行：开' : '飞行：关');
          }
          lastSpace = now2;
        }
        input.jump = down; break;
      case 'KeyG': if (down) toggleCreative(); break;
      default:
        if (/^Digit[1-9]$/.test(e.code) && down) {
          WC.hud.setHotbarSel(+e.code.slice(5) - 1);
          WC.audio.pop();
        }
    }
  }
  function onMouseDown(e) {
    if (state === 'playing' && document.pointerLockElement !== canvas) { lockPointer(); return; }
    if (state !== 'playing') return;
    if (e.button === 0) { mining = true; digSndT = 0; }
    else if (e.button === 2) { placing = true; placeT = 0; }
    else if (e.button === 1) {
      e.preventDefault();
      var hit = getTarget();
      if (hit && B.PLACEABLE.indexOf(hit.id) >= 0) {
        WC.hud.setHotbarSel(WC.hud.getSel());
        WC.hud.hotbar[WC.hud.getSel()] = hit.id;
        WC.hud.renderHotbar();
        WC.hud.toast(B.DEFS[hit.id].name);
        WC.audio.pop();
      }
    }
  }
  function onMouseUp(e) {
    if (e.button === 0) mining = false;
    if (e.button === 2) placing = false;
  }
  function bindEvents() {
    window.addEventListener('resize', function () {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
    document.addEventListener('pointerlockchange', function () {
      if (document.pointerLockElement !== canvas && state === 'playing') pauseGame();
    });
    document.addEventListener('mousemove', function (ev) {
      if (state !== 'playing' || document.pointerLockElement !== canvas) return;
      var s = 0.0023;
      WC.player.addYaw(ev.movementX * s);
      WC.player.addPitch(ev.movementY * s);
    });
    document.addEventListener('keydown', onKey);
    document.addEventListener('keyup', onKey);
    canvas.addEventListener('mousedown', onMouseDown);
    document.addEventListener('mouseup', onMouseUp);
    document.addEventListener('contextmenu', function (e) { e.preventDefault(); });
    document.addEventListener('wheel', function (e) {
      if (state !== 'playing') return;
      WC.hud.scrollSel(e.deltaY > 0 ? 1 : -1);
      WC.audio.pop();
    }, { passive: true });
    window.addEventListener('blur', function () {
      input.forward = input.back = input.left = input.right = input.jump = input.sneak = input.sprint = false;
      mining = placing = false;
    });
    window.addEventListener('beforeunload', saveNow);

    $('btnStart').addEventListener('click', startGame);
    $('btnResume').addEventListener('click', resumeGame);
    $('btnRespawn').addEventListener('click', respawn);
    $('btnReset').addEventListener('click', resetWorld);
    $('btnReset2').addEventListener('click', resetWorld);
    $('btnHelp').addEventListener('click', function () { var b = $('helpBox'); b.innerHTML = HELP; b.classList.toggle('hidden'); });
    $('btnHelp2').addEventListener('click', function () { var b = $('helpBox2'); b.innerHTML = HELP; b.classList.toggle('hidden'); });
  }

  // ---------------- 存档 ----------------
  function saveNow() {
    if (!started) return;
    try {
      var P = WC.player;
      localStorage.setItem(C.SAVE_KEY, JSON.stringify({
        v: 1,
        world: W.collectSave(),
        time: timeOfDay, rain: raining, stats: stats,
        player: { x: P.pos.x, y: P.pos.y, z: P.pos.z, yaw: P.yaw, pitch: P.pitch, creative: P.creative },
        hotbar: WC.hud.hotbar, sel: WC.hud.getSel()
      }));
    } catch (e) {}
  }

  // ---------------- 调试 ----------------
  function fmtTime(t01) {
    var mins = Math.floor(((t01 * 24 + 6) % 24) * 60);
    var h = Math.floor(mins / 60), m = mins % 60;
    return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
  }
  function updateDebug() {
    var P = WC.player, p = P.pos;
    var x = Math.floor(p.x), z = Math.floor(p.z);
    var h = W.heightAt(x, z);
    var biome = W.biomeOf(h, W.tempAt(x, z), W.humidAt(x, z));
    var bn = { snow: '雪山', desert: '沙漠', forest: '森林', plains: '平原' }[biome] || biome;
    WC.hud.debug(
      'WebCraft 1.0  ' + fps.toFixed(0) + ' fps\n' +
      'XYZ: ' + p.x.toFixed(1) + ' / ' + p.y.toFixed(1) + ' / ' + p.z.toFixed(1) + '\n' +
      '区块: ' + Math.floor(p.x / 16) + ' ' + Math.floor(p.z / 16) + '  生物群系: ' + bn + '\n' +
      '时间: ' + fmtTime(timeOfDay) + '  天气: ' + (raining ? '雨' : '晴') + '\n' +
      '挖掘 ' + stats.mined + '  放置 ' + stats.placed + '  模式: ' + (P.creative ? '创造' : '生存') + (P.flying ? '(飞行)' : '') + '\n' +
      '渲染区块: ' + chunkMeshes.size + '  draw calls: ' + renderer.info.render.calls);
  }

  // ---------------- 主循环 ----------------
  var lastT = performance.now();
  function loop(now) {
    requestAnimationFrame(loop);
    var dt = Math.min(0.05, (now - lastT) / 1000);
    lastT = now;
    if (dt > 0) fps = fps * 0.95 + (1 / dt) * 0.05;

    if (state === 'menu' || state === 'dead') {
      // 菜单环绕镜头
      menuOrbit += dt * 0.06;
      var sp = WC.player.pos;
      var gy = W.heightAt(Math.floor(sp.x), Math.floor(sp.z));
      camera.position.set(sp.x + Math.cos(menuOrbit) * 24, Math.max(gy + 12, sp.y + 8), sp.z + Math.sin(menuOrbit) * 24);
      camera.lookAt(sp.x, sp.y + 2, sp.z);
    } else if (state === 'playing') {
      elapsed += dt;
      timeOfDay = (timeOfDay + dt / C.DAY_LENGTH) % 1;
      WC.player.update(dt, input, camera);

      // 疾跑 FOV
      var moving = input.forward || input.back || input.left || input.right;
      var targetFov = fovBase + ((input.sprint && moving) ? 9 : 0);
      if (Math.abs(camera.fov - targetFov) > 0.05) {
        camera.fov += (targetFov - camera.fov) * Math.min(1, dt * 10);
        camera.updateProjectionMatrix();
      }

      handleInteraction(dt);
      WC.viewmodel.update(dt, {
        moving: moving, onGround: WC.player.onGround,
        speed: Math.hypot(WC.player.vel.x, WC.player.vel.z)
      });

      weatherT -= dt;
      if (weatherT <= 0) {
        weatherT = 60 + Math.random() * 120;
        raining = Math.random() < (raining ? 0.55 : 0.32);
        WC.sky.setRain(raining);
        WC.particles.setRain(raining);
        WC.audio.setRain(raining);
        if (raining) WC.hud.toast('下雨了…');
      }

      saveT += dt;
      if (saveT > 12) { saveT = 0; saveNow(); }
      cleanupT += dt;
      if (cleanupT > 3) { cleanupT = 0; removeFarMeshes(); }
    }

    pumpChunks(state === 'menu' ? 6 : 2, state === 'menu' ? 6 : 2);
    WC.sky.update(dt, camera.position.x, camera.position.y, camera.position.z, camera, timeOfDay, elapsed);
    WC.particles.update(dt, camera.position.x, camera.position.y, camera.position.z);

    var L = WC.sky.getDayLight();
    matOpaque.color.setScalar(L);
    matCutout.color.setScalar(L);
    matWater.color.setScalar(L);

    WC.viewmodel.group.visible = (state === 'playing' || state === 'paused');
    var cb = WC.hud.currentBlock() || 0;
    if (cb !== lastVM) { lastVM = cb; WC.viewmodel.setBlock(cb || null); }

    if (WC.hud.el.waterOverlay) WC.hud.setWaterOverlay(state === 'playing' && WC.player.headInWater);
    WC.hud.update(dt, WC.player);
    if (debugOn) updateDebug();
    renderer.render(scene, camera);
  }

  // ---------------- 自动化探针（E2E 用）----------------
  if (AUTOSTART) {
    setTimeout(function () {
      try {
        var c2 = document.createElement('canvas');
        c2.width = 160; c2.height = 100;
        var cx2 = c2.getContext('2d');
        cx2.drawImage(renderer.domElement, 0, 0, 160, 100);
        var d = cx2.getImageData(0, 0, 160, 100).data;
        var s = 0, n = d.length / 4;
        for (var i = 0; i < d.length; i += 4) s += (d[i] + d[i + 1] + d[i + 2]) / 3;
        document.title = 'WC-OK bright=' + (s / n).toFixed(1) +
          ' calls=' + renderer.info.render.calls +
          ' tris=' + renderer.info.render.triangles +
          ' chunks=' + chunkMeshes.size;
      } catch (err) { document.title = 'WC-PROBE-ERR ' + err.message; }
    }, 4500);
  }

  return { init: init, onPlayerDeath: onPlayerDeath, findSpawn: findSpawn, resetWorld: resetWorld };
})();

WC.main.init();
","path":"js/main.js"}

