{"content":"// 生物生态：猪/羊/僵尸（AI、物理、战斗、掉落）+ 掉落物拾取
window.WC = window.WC || {};
WC.entities = (function () {
  var C = WC.cfg, B = WC.blocks, W = WC.world, ID = B.ID;
  var scene, camera;
  var mobs = [], drops = [];
  var spawnT = 1.5;

  var TYPES = {
    pig:    { name: '猪', w: 0.42, h: 0.95, hp: 10, speed: 1.15, hostile: false, drop: { food: 4, color: 0xdf9078 } },
    sheep:  { name: '羊', w: 0.42, h: 1.2,  hp: 8,  speed: 1.05, hostile: false, drop: { food: 2, color: 0xe6e2da } },
    zombie: { name: '僵尸', w: 0.3, h: 1.92, hp: 20, speed: 2.35, hostile: true, drop: null }
  };

  function fl(v) { return Math.floor(v); }
  function newMat(mats, color) {
    var m = new THREE.MeshLambertMaterial({ color: color });
    mats.push(m);
    return m;
  }
  function box(w, h, d, m) { return new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); }

  // 四足动物模型（面朝 -Z）
  function quadModel(bodyC, headC, legC, s, snoutC) {
    var g = new THREE.Group(), mats = [];
    var body = box(s.bw, s.bh, s.bl, newMat(mats, bodyC));
    body.position.y = s.legH + s.bh / 2;
    g.add(body);
    var head = box(s.hs, s.hs, s.hs, newMat(mats, headC));
    head.position.set(0, s.legH + s.bh * 0.8, -(s.bl / 2 + s.hs / 2 - 0.06));
    g.add(head);
    if (snoutC) {
      var sn = box(0.24, 0.16, 0.09, newMat(mats, snoutC));
      sn.position.set(0, head.position.y - s.hs * 0.18, head.position.z - s.hs / 2 - 0.045);
      g.add(sn);
    }
    var eyeM = newMat(mats, 0x1a1a1a);
    [[-0.09, 0.09], [0.09, 0.09]].forEach(function (p) {
      var e = box(0.06, 0.06, 0.02, eyeM);
      e.position.set(head.position.x + p[0], head.position.y + s.hs * 0.12, head.position.z - s.hs / 2 - 0.012);
      g.add(e);
    });
    var legs = [];
    var lx = s.bw / 2 - 0.07, lz = s.bl / 2 - 0.09;
    [[-lx, -lz], [lx, -lz], [-lx, lz], [lx, lz]].forEach(function (p) {
      var lg = new THREE.BoxGeometry(0.15, s.legH, 0.15);
      lg.translate(0, -s.legH / 2, 0);
      var lm = new THREE.Mesh(lg, newMat(mats, legC));
      lm.position.set(p[0], s.legH, p[1]);
      g.add(lm);
      legs.push(lm);
    });
    g.userData = { mats: mats, legs: legs };
    return g;
  }

  function zombieModel() {
    var g = new THREE.Group(), mats = [];
    var skin = 0x5d8f4f, shirt = 0x2f7d7d, pants = 0x3d3573;
    var legs = [];
    [[-0.12], [0.12]].forEach(function (p) {
      var lg = new THREE.BoxGeometry(0.22, 0.72, 0.22);
      lg.translate(0, -0.36, 0);
      var lm = new THREE.Mesh(lg, newMat(mats, pants));
      lm.position.set(p[0], 0.72, 0);
      g.add(lm);
      legs.push(lm);
    });
    var body = box(0.5, 0.72, 0.26, newMat(mats, shirt));
    body.position.y = 1.08;
    g.add(body);
    [[-0.36], [0.36]].forEach(function (p) {
      var ag = new THREE.BoxGeometry(0.2, 0.66, 0.2);
      ag.translate(0, -0.3, 0);
      var am = new THREE.Mesh(ag, newMat(mats, skin));
      am.position.set(p[0], 1.4, -0.05);
      am.rotation.x = -1.25;
      g.add(am);
    });
    var head = box(0.48, 0.48, 0.48, newMat(mats, skin));
    head.position.y = 1.68;
    g.add(head);
    var eyeM = newMat(mats, 0x101418);
    [[-0.11], [0.11]].forEach(function (p) {
      var e = box(0.1, 0.06, 0.02, eyeM);
      e.position.set(p[0], 1.72, -0.25);
      g.add(e);
    });
    g.userData = { mats: mats, legs: legs };
    return g;
  }

  function init(sc, cam) {
    scene = sc; camera = cam;
  }

  function spawn(type, x, y, z) {
    var d = TYPES[type];
    var group = type === 'zombie' ? zombieModel()
      : type === 'pig' ? quadModel(0xeea3a3, 0xf0adad, 0xdd9090,
          { bw: 0.56, bh: 0.5, bl: 0.9, hs: 0.46, legH: 0.3 }, 0xd97f7f)
      : quadModel(0xe9e5dc, 0xd8b98c, 0xcfc9bd,
          { bw: 0.6, bh: 0.6, bl: 0.85, hs: 0.4, legH: 0.45 }, null);
    scene.add(group);
    var m = {
      type: type, def: d, group: group, mats: group.userData.mats, legs: group.userData.legs,
      pos: { x: x, y: y, z: z }, vel: { x: 0, y: 0, z: 0 },
      yaw: Math.random() * Math.PI * 2, hp: d.hp,
      t: 0.5 + Math.random(), walk: false, onGround: false, blocked: false,
      phase: Math.random() * 6, hurtT: 0, fleeT: 0, atkT: 0,
      dead: false, deathT: 0, removed: false
    };
    group.position.set(x, y, z);
    mobs.push(m);
    return m;
  }

  function removeMob(m) {
    m.removed = true;
    scene.remove(m.group);
    m.group.traverse(function (o) { if (o.geometry) o.geometry.dispose(); });
    m.mats.forEach(function (mt) { mt.dispose(); });
  }
  function removeDrop(d) {
    d.removed = true;
    scene.remove(d.mesh);
    d.mesh.geometry.dispose();
    d.mesh.material.dispose();
  }

  // ---------- 物理（与玩家一致的 AABB 分轴碰撞） ----------
  function boxCollides(px, py, pz, w, h) {
    var x0 = fl(px - w), x1 = fl(px + w);
    var y0 = fl(py), y1 = fl(py + h);
    var z0 = fl(pz - w), z1 = fl(pz + w);
    for (var x = x0; x <= x1; x++)
      for (var y = y0; y <= y1; y++)
        for (var z = z0; z <= z1; z++)
          if (W.isSolidAt(x, y, z)) return true;
    return false;
  }
  function moveBody(e, dt) {
    var w = e.def.w, h = e.def.h;
    var mx = e.vel.x * dt, my = e.vel.y * dt, mz = e.vel.z * dt;
    var steps = Math.max(1, Math.ceil(Math.max(Math.abs(mx), Math.abs(my), Math.abs(mz)) / 0.2));
    var sx = mx / steps, sy = my / steps, sz = mz / steps;
    for (var i = 0; i < steps; i++) {
      if (sx !== 0) {
        if (!boxCollides(e.pos.x + sx, e.pos.y, e.pos.z, w, h)) e.pos.x += sx;
        else { e.vel.x = 0; e.blocked = true; sx = 0; }
      }
      if (sz !== 0) {
        if (!boxCollides(e.pos.x, e.pos.y, e.pos.z + sz, w, h)) e.pos.z += sz;
        else { e.vel.z = 0; e.blocked = true; sz = 0; }
      }
      if (sy !== 0) {
        if (!boxCollides(e.pos.x, e.pos.y + sy, e.pos.z, w, h)) e.pos.y += sy;
        else {
          if (sy < 0) e.onGround = true;
          e.vel.y = 0; sy = 0;
        }
      }
    }
    // 卡住上推
    var tries = 0;
    while (boxCollides(e.pos.x, e.pos.y, e.pos.z, w, h) && tries++ < 40) e.pos.y += 0.05;
  }

  function skyExposed(x, y, z) {
    var bx = fl(x), bz = fl(z);
    for (var yy = fl(y) + 1; yy < Math.min(C.HEIGHT, fl(y) + 26); yy++)
      if (B.isOpaque(W.getBlock(bx, yy, bz))) return false;
    return true;
  }

  function setFlash(m, hex) {
    m.mats.forEach(function (mt) { mt.emissive.setHex(hex); });
  }

  function hurtMob(m, dmg, kx, kz) {
    if (m.dead) return;
    m.hp -= dmg;
    m.hurtT = 0.35;
    setFlash(m, 0xaa2222);
    m.vel.x += kx * 7; m.vel.z += kz * 7; m.vel.y = Math.max(m.vel.y, 4.6);
    if (m.def.hostile) WC.audio.groan();
    else { WC.audio.oink(); m.fleeT = 3; }
    if (m.hp <= 0) killMob(m);
  }

  function killMob(m) {
    m.dead = true; m.deathT = 0;
    setFlash(m, 0x000000);
    if (m.def.drop) spawnDrop(m.pos.x, m.pos.y + 0.4, m.pos.z, m.def.drop);
  }

  // ---------- 掉落物 ----------
  function spawnDrop(x, y, z, dropDef) {
    var mesh = new THREE.Mesh(
      new THREE.BoxGeometry(0.26, 0.26, 0.26),
      new THREE.MeshLambertMaterial({ color: dropDef.color }));
    mesh.position.set(x, y, z);
    scene.add(mesh);
    drops.push({
      mesh: mesh, food: dropDef.food, color: dropDef.color,
      pos: { x: x, y: y, z: z }, vel: { x: (Math.random() - 0.5) * 1.5, y: 3, z: (Math.random() - 0.5) * 1.5 },
      def: { w: 0.13, h: 0.26 }, onGround: false, blocked: false,
      age: 0, removed: false
    });
  }

  // ---------- 玩家攻击 ----------
  function rayBox(ox, oy, oz, dx, dy, dz, e, reach) {
    var w = e.def.w + 0.15, h = e.def.h;
    var tmin = 0, tmax = reach;
    function axis(o, d, mn, mx) {
      if (Math.abs(d) < 1e-9) return o >= mn && o <= mx;
      var t1 = (mn - o) / d, t2 = (mx - o) / d;
      if (t1 > t2) { var t = t1; t1 = t2; t2 = t; }
      if (t1 > tmin) tmin = t1;
      if (t2 < tmax) tmax = t2;
      return tmin <= tmax;
    }
    if (!axis(ox, dx, e.pos.x - w, e.pos.x + w)) return null;
    if (!axis(oy, dy, e.pos.y, e.pos.y + h)) return null;
    if (!axis(oz, dz, e.pos.z - w, e.pos.z + w)) return null;
    return tmin;
  }
  function tryAttack(origin, dir, reach) {
    var best = null, bd = reach;
    for (var i = 0; i < mobs.length; i++) {
      var m = mobs[i];
      if (m.dead) continue;
      var t = rayBox(origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, m, reach);
      if (t !== null && t < bd) { bd = t; best = m; }
    }
    if (!best) return false;
    var l = Math.hypot(dir.x, dir.z) || 1;
    hurtMob(best, 4, dir.x / l, dir.z / l);
    return true;
  }

  // ---------- AI ----------
  function updateMob(m, dt, active) {
    if (m.dead) {
      m.deathT += dt;
      m.group.rotation.z = Math.min(1, m.deathT / 0.3) * Math.PI / 2;
      if (m.deathT > 0.45) {
        var op = Math.max(0, 1 - (m.deathT - 0.45) / 0.4);
        m.mats.forEach(function (mt) { mt.transparent = true; mt.opacity = op; });
      }
      if (m.deathT > 0.9) removeMob(m);
      return;
    }
    if (!active) return;

    if (m.hurtT > 0) {
      m.hurtT -= dt;
      if (m.hurtT <= 0) setFlash(m, 0x000000);
    }

    var d = m.def;
    var P = WC.player.pos;
    var dx = P.x - m.pos.x, dz = P.z - m.pos.z;
    var distP = Math.hypot(dx, dz);
    var walking = false, spd = d.speed;

    if (d.hostile) {
      // 僵尸：夜晚或黑暗时追击玩家
      if (!WC.player.creative && distP < 18 && Math.abs(P.y - m.pos.y) < 7) {
        m.yaw = Math.atan2(-dx, -dz);
        walking = distP > 1.1;
        m.atkT -= dt;
        if (distP < 1.6 && m.atkT <= 0) {
          m.atkT = 1.1;
          WC.player.damage(2, '僵尸');
        }
        if (Math.random() < dt * 0.22) WC.audio.groan();
      } else {
        m.t -= dt;
        if (m.t <= 0) {
          m.walk = Math.random() < 0.6;
          m.yaw = Math.random() * Math.PI * 2;
          m.t = 1.5 + Math.random() * 3;
        }
        walking = m.walk;
      }
      // 白天日燃
      if (WC.sky.getSunHeight() > 0.12 && skyExposed(m.pos.x, m.pos.y + d.h, m.pos.z)) {
        m.hp -= dt * 2.2;
        if (Math.random() < dt * 7) {
          WC.particles.emitBurst(m.pos.x, m.pos.y + 1.2, m.pos.z, [1, 0.5, 0.1], 2, 1.6);
        }
        if (m.hurtT <= 0) setFlash(m, 0x662200);
        if (m.hp <= 0) { killMob(m); return; }
      }
    } else {
      // 被动生物：受伤逃跑 / 随机游荡
      if (m.fleeT > 0) {
        m.fleeT -= dt;
        m.yaw = Math.atan2(dx, dz); // 远离玩家
        spd = d.speed * 2.2;
        walking = true;
      } else {
        m.t -= dt;
        if (m.t <= 0) {
          m.walk = Math.random() < 0.55;
          m.yaw = Math.random() * Math.PI * 2;
          m.t = 1.5 + Math.random() * 3.5;
        }
        walking = m.walk;
      }
      // 不主动下水：前方是水则转向
      var fx2 = -Math.sin(m.yaw), fz2 = -Math.cos(m.yaw);
      var aheadB = W.getBlock(fl(m.pos.x + fx2 * 0.9), fl(m.pos.y + 0.1), fl(m.pos.z + fz2 * 0.9));
      if (aheadB === ID.WATER) { m.yaw += Math.PI * (0.6 + Math.random() * 0.8); }
    }

    // 水：上浮
    var inW = W.getBlock(fl(m.pos.x), fl(m.pos.y + 0.3), fl(m.pos.z)) === ID.WATER;
    if (inW) {
      m.vel.y = Math.min(m.vel.y + 20 * dt, 2.6);
      spd *= 0.5;
    } else {
      m.vel.y -= C.GRAVITY * dt;
    }

    var fx = -Math.sin(m.yaw), fz = -Math.cos(m.yaw);
    var wishX = walking ? fx * spd : 0, wishZ = walking ? fz * spd : 0;
    var acc = m.onGround ? 10 : 3;
    m.vel.x += (wishX - m.vel.x) * Math.min(1, acc * dt);
    m.vel.z += (wishZ - m.vel.z) * Math.min(1, acc * dt);

    m.blocked = false;
    m.onGround = false;
    moveBody(m, dt);
    // 前方受阻自动跳
    if (m.blocked && m.onGround && walking && !inW) m.vel.y = 7.4;

    // 走路摆腿
    var sp2 = Math.hypot(m.vel.x, m.vel.z);
    m.phase += dt * (2 + sp2 * 2.4);
    var amp = Math.min(0.75, sp2 * 0.4);
    var sw = Math.sin(m.phase) * amp;
    for (var li = 0; li < m.legs.length; li++) {
      m.legs[li].rotation.x = (li === 0 || li === 3) ? sw : -sw;
    }

    m.group.position.set(m.pos.x, m.pos.y, m.pos.z);
    m.group.rotation.y = m.yaw;

    if (m.pos.y < -12) removeMob(m);
  }

  function updateDrop(d, dt, active) {
    if (d.removed) return;
    d.age += dt;
    d.vel.y -= C.GRAVITY * 0.6 * dt;
    d.vel.x *= Math.pow(0.9, dt * 60);
    d.vel.z *= Math.pow(0.9, dt * 60);
    moveBody(d, dt);
    d.mesh.rotation.y += dt * 2.2;

    if (!active) { d.mesh.position.set(d.pos.x, d.pos.y + 0.12, d.pos.z); return; }

    var P = WC.player.pos;
    var dx = P.x - d.pos.x, dy = (P.y + 0.9) - d.pos.y, dz = P.z - d.pos.z;
    var dist = Math.hypot(dx, dy, dz);
    if (dist < 2 && d.age > 0.5) {
      // 磁吸
      d.pos.x += dx / dist * 7 * dt;
      d.pos.y += dy / dist * 7 * dt;
      d.pos.z += dz / dist * 7 * dt;
      if (dist < 0.9) {
        WC.player.addHunger(d.food);
        WC.hud.toast('获得食物  饥饿 +' + d.food);
        WC.audio.pop();
        WC.particles.emitBurst(d.pos.x, d.pos.y, d.pos.z,
          [(d.color >> 16 & 255) / 255, (d.color >> 8 & 255) / 255, (d.color & 255) / 255], 6, 2);
        removeDrop(d);
        return;
      }
    }
    if (d.age > 90) { removeDrop(d); return; }
    d.mesh.position.set(d.pos.x, d.pos.y + 0.12 + Math.sin(d.age * 3) * 0.04, d.pos.z);
  }

  // ---------- 刷怪 ----------
  function trySpawnOnce() {
    if (mobs.length >= 14) return;
    var P = WC.player.pos;
    var passiveN = 0, hostileN = 0;
    mobs.forEach(function (m) { if (m.dead) return; m.def.hostile ? hostileN++ : passiveN++; });
    var sunH = WC.sky.getSunHeight();
    var wantZombie = hostileN < 5 && sunH < -0.02;
    var wantPassive = passiveN < 8;

    for (var attempt = 0; attempt < 6; attempt++) {
      var a = Math.random() * Math.PI * 2;
      var r = 22 + Math.random() * 42;
      var x = fl(P.x + Math.cos(a) * r), z = fl(P.z + Math.sin(a) * r);
      if (!W.hasChunk(fl(x / C.CHUNK), fl(z / C.CHUNK))) continue;
      var y = W.highestBlockY(x, z);
      if (y < 2 || y >= C.HEIGHT - 3) continue;
      var ground = W.getBlock(x, y, z);
      var above = W.getBlock(x, y + 1, z);
      var above2 = W.getBlock(x, y + 2, z);
      if (above !== 0 || above2 !== 0) continue;
      if (W.getBlock(x, y + 1, z + 1) !== 0 || W.getBlock(x + 1, y + 1, z) !== 0) continue;

      if (wantZombie && Math.random() < 0.6 && ground !== ID.WATER && !B.DEFS[ground].water) {
        spawn('zombie', x + 0.5, y + 1.02, z + 0.5);
        return;
      }
      if (wantPassive && (ground === ID.GRASS || ground === ID.SNOW)) {
        spawn(Math.random() < 0.55 ? 'pig' : 'sheep', x + 0.5, y + 1.02, z + 0.5);
        return;
      }
    }
  }

  function update(dt, active) {
    var i;
    if (active) {
      spawnT -= dt;
      if (spawnT <= 0) { spawnT = 2; trySpawnOnce(); }
      // 距离过远清除
      var P = WC.player.pos;
      for (i = 0; i < mobs.length; i++) {
        var m = mobs[i];
        if (!m.dead && Math.hypot(m.pos.x - P.x, m.pos.z - P.z) > 95) removeMob(m);
      }
    }
    for (i = 0; i < mobs.length; i++) updateMob(mobs[i], dt, active);
    for (i = 0; i < drops.length; i++) updateDrop(drops[i], dt, active);
    mobs = mobs.filter(function (m) { return !m.removed; });
    drops = drops.filter(function (d) { return !d.removed; });
  }

  function debugSpawn() {
    var P = WC.player.pos;
    var n = 0;
    for (var a = 0; a < 6; a++) {
      var ang = a * Math.PI / 3;
      var x = P.x + Math.cos(ang) * 7, z = P.z + Math.sin(ang) * 7;
      var y = W.heightAt(fl(x), fl(z)) + 1.1;
      var t = a < 2 ? 'pig' : (a < 4 ? 'sheep' : 'zombie');
      spawn(t, x, y, z);
      n++;
    }
    return n;
  }

  function countMobs() {
    var n = 0;
    mobs.forEach(function (m) { if (!m.dead) n++; });
    return n;
  }
  function countDrops() { return drops.length; }
  function clear() {
    mobs.forEach(removeMob);
    drops.forEach(removeDrop);
    mobs = []; drops = [];
  }

  return {
    init: init, update: update, tryAttack: tryAttack,
    debugSpawn: debugSpawn, countMobs: countMobs, countDrops: countDrops, clear: clear
  };
})();
